import music21
from music21 import stream, note, chord, meter, tempo, key, instrument, dynamics, expressions, metadata, pitch, bar, articulations

score = stream.Score(id='between_signal_and_breath')
score.metadata = metadata.Metadata()
score.metadata.title = 'Between Signal and Breath'
score.metadata.composer = 'ChatGPT'

score.insert(0, tempo.MetronomeMark(number=72, text='calm clock, breathing line'))
score.insert(64, tempo.MetronomeMark(number=84, text='more luminous'))
score.insert(96, tempo.MetronomeMark(number=60, text='spacious'))

base = 62
cell = [0, 3, 7, 11, 14, 6, 9, 1]
mirror = [0, -1, 2, -5, 7, 3, -2, 4]
glow = [0, 2, 5, 6, 9, 11, 14, 17]


def pname(midi_number):
    p = pitch.Pitch()
    p.midi = int(midi_number)
    return p.nameWithOctave


def N(p, ql, stacc=False, accent=False, ten=False):
    if isinstance(p, int):
        p = pname(p)
    x = note.Note(p)
    x.duration.quarterLength = ql
    if stacc:
        x.articulations.append(articulations.Staccato())
    if accent:
        x.articulations.append(articulations.Accent())
    if ten:
        x.articulations.append(articulations.Tenuto())
    return x


def R(ql):
    x = note.Rest()
    x.duration.quarterLength = ql
    return x


def C(ps, ql):
    converted = []
    for item in ps:
        converted.append(pname(item) if isinstance(item, int) else item)
    x = chord.Chord(converted)
    x.duration.quarterLength = ql
    return x


def common_markings(m, number, dyn=None, text=None):
    if number == 1:
        m.insert(0, meter.TimeSignature('4/4'))
        m.insert(0, key.KeySignature(0))
    if dyn:
        m.insert(0, dynamics.Dynamic(dyn))
    if text:
        t = expressions.TextExpression(text)
        t.placement = 'above'
        m.insert(0, t)


def finish_measure(m):
    d = round(float(m.duration.quarterLength), 5)
    if d < 4.0:
        m.append(R(4.0 - d))
    return m


def make_measure(number, events, dyn=None, text=None):
    m = stream.Measure(number=number)
    common_markings(m, number, dyn, text)
    for ev in events:
        m.append(ev)
    finish_measure(m)
    if number == 36:
        m.rightBarline = bar.Barline('final')
    return m


piano_harmonies = [
    ['D2', 'A2', 'D3', 'F4', 'C#5'],
    ['A1', 'E2', 'C#3', 'G4', 'B4'],
    ['F2', 'C3', 'A3', 'E4', 'G#4'],
    ['C#2', 'G#2', 'E3', 'B3', 'F4'],
    ['E2', 'B2', 'G3', 'C#4', 'A4'],
    ['G#1', 'D#2', 'B2', 'E4', 'F4'],
    ['B1', 'F#2', 'D3', 'A3', 'E4'],
    ['E-2', 'B-2', 'F3', 'A4', 'C#5'],
]


def piano_events(number):
    idx = (number - 1) % 8
    if number <= 8:
        return [C(piano_harmonies[idx], 2.0), R(0.5), C(piano_harmonies[(idx + 3) % 8], 1.5)]
    if number <= 16:
        bass = ['D2', 'A1', 'F2', 'E2', 'G2', 'B-1', 'C#2', 'A1']
        upper = [['F4', 'C#5'], ['E4', 'B4'], ['A3', 'G#4'], ['B3', 'F4'], ['C#4', 'A4'], ['E4', 'F4'], ['D4', 'A4'], ['F4', 'C#5']]
        return [
            C([bass[idx]] + upper[idx], 0.75), R(0.25),
            C([bass[(idx + 3) % 8], upper[(idx + 1) % 8][0]], 0.5),
            C(upper[(idx + 2) % 8], 0.5),
            C([bass[(idx + 5) % 8]] + upper[(idx + 4) % 8], 1.0),
            R(0.5), C(upper[(idx + 6) % 8], 0.5)
        ]
    if number <= 24:
        out = []
        shift = [0, 2, -1, 5, 3, 6, 1, 4][idx]
        for j in range(8):
            low = base - 24 + glow[(idx + j) % len(glow)]
            up_a = base + 12 + cell[(idx + (2 * j)) % len(cell)] + shift
            up_b = base + 24 + mirror[(idx + j) % len(mirror)]
            if j % 2 == 0:
                out.append(C([low, up_a, up_b], 0.5))
            else:
                out.append(C([up_a, up_b], 0.5))
        return out
    if number <= 32:
        return [
            C(['D2', 'A2', pname(base + glow[idx]), pname(base + 12 + cell[idx])], 1.5),
            C(['C#3', pname(base + 7 + mirror[idx])], 0.5),
            R(0.5),
            C(['E2', 'B2', pname(base + 5 + cell[(idx + 3) % 8]), pname(base + 17 + mirror[(idx + 2) % 8])], 1.5)
        ]
    if number == 33:
        return [C(['D2', 'A2', 'E4', 'F#4', 'C#5'], 2.0), C(['C#2', 'G#2', 'D4', 'F4', 'B4'], 2.0)]
    if number == 34:
        return [C(['B1', 'F#2', 'D4', 'A4'], 1.5), R(0.5), C(['E2', 'B2', 'G#3', 'E4'], 2.0)]
    if number == 35:
        return [C(['F2', 'C3', 'A3', 'E4'], 1.0), C(['A1', 'E2', 'C#4', 'G4'], 1.0), R(1.0), C(['D2', 'A2', 'F4'], 1.0)]
    return [C(['D2', 'A2', 'D3', 'A3', 'D4', 'F#4'], 4.0)]


def violin_events(number):
    idx = (number - 1) % 8
    if number <= 8:
        if number % 2 == 1:
            return [R(1.0), N(base + 12 + cell[idx], 1.25, ten=True), N(base + 12 + cell[(idx + 1) % 8], 0.75), R(1.0)]
        return [R(0.5), N(base + 12 + cell[idx], 0.5), N(base + 12 + cell[(idx + 2) % 8], 1.0, ten=True), R(0.5), N(base + 12 + cell[(idx + 5) % 8], 1.5)]
    if number <= 16:
        trans = [0, 2, 5, 3][(number - 9) // 2]
        rhythms = [0.5, 0.5, 1.0, 0.5, 0.5, 1.0]
        return [N(base + 14 + cell[(idx + j) % 8] + trans, rhythms[j], accent=(j == 2)) for j in range(6)]
    if number <= 24:
        shift = [0, 1, 4, 6, 2, 5, -1, 3][idx]
        return [N(base + 19 + cell[(idx + (3 * j)) % 8] + shift, 0.5, accent=(j in [0, 3, 6])) for j in range(8)]
    if number <= 32:
        return [N(base + 17 + glow[idx], 1.5, ten=True), R(0.5), N(base + 12 + cell[(idx + 4) % 8], 2.0, ten=True)]
    if number == 33:
        return [N('D6', 2.0, ten=True), N('C#6', 2.0, ten=True)]
    if number == 34:
        return [N('B5', 1.5, ten=True), R(0.5), N('E6', 2.0, ten=True)]
    if number == 35:
        return [N('A5', 1.5), N('F5', 1.5), N('D5', 1.0, ten=True)]
    return [N('D5', 4.0, ten=True)]


def clarinet_events(number):
    idx = (number - 1) % 8
    if number <= 8:
        return [N(base - 2 + mirror[idx], 1.0, ten=True), R(0.5), N(base + cell[(idx + 4) % 8], 1.5), R(1.0)]
    if number <= 16:
        trans = [0, -2, 3, 1][(number - 9) // 2]
        return [R(0.5), N(base + mirror[idx] + trans, 1.0), N(base + cell[(idx + 2) % 8] + trans, 0.5, stacc=True), R(0.5), N(base + mirror[(idx + 5) % 8] + 7 + trans, 1.5, ten=True)]
    if number <= 24:
        out = []
        for j in range(8):
            if j in [2, 5]:
                out.append(R(0.5))
            else:
                out.append(N(base + 2 + mirror[(idx + (2 * j)) % 8] + [0, 2, 4, 5][j % 4], 0.5, accent=(j == 7)))
        return out
    if number <= 32:
        return [N(base - 5 + glow[(idx + 2) % 8], 2.0, ten=True), N(base + mirror[idx], 1.0), R(1.0)]
    if number == 33:
        return [N('F#4', 2.0, ten=True), N('E4', 2.0, ten=True)]
    if number == 34:
        return [N('G#4', 1.0), N('A4', 1.0), N('B4', 2.0, ten=True)]
    if number == 35:
        return [N('F4', 2.0, ten=True), N('E4', 1.0), R(1.0)]
    return [N('A3', 4.0, ten=True)]


def cello_events(number):
    idx = (number - 1) % 8
    pedal = ['D2', 'A1', 'F2', 'C#2', 'E2', 'G#1', 'B1', 'E-2']
    if number <= 8:
        return [N(pedal[idx], 4.0, ten=True)]
    if number <= 16:
        return [N(pedal[idx], 1.0, stacc=True), R(0.5), N(pedal[(idx + 3) % 8], 0.5, stacc=True), N(pedal[(idx + 5) % 8], 1.0), N(pedal[(idx + 2) % 8], 1.0)]
    if number <= 24:
        out = []
        for j in range(8):
            out.append(N(base - 24 + glow[(idx + j) % 8], 0.5, stacc=(j % 2 == 1), accent=(j == 0)))
        return out
    if number <= 32:
        return [N(pedal[idx], 2.5, ten=True), R(0.5), N(pedal[(idx + 2) % 8], 1.0, ten=True)]
    if number == 33:
        return [N('D2', 4.0, ten=True)]
    if number == 34:
        return [N('B1', 2.0, ten=True), N('E2', 2.0, ten=True)]
    if number == 35:
        return [N('F2', 1.5, ten=True), N('A1', 1.5), N('D2', 1.0, ten=True)]
    return [N('D2', 4.0, ten=True)]


def build_part(part_name, instr, event_function, dyn_map, text_map=None):
    if text_map is None:
        text_map = {}
    p = stream.Part(id=part_name)
    p.partName = part_name
    p.insert(0, instr)
    for number in range(1, 37):
        p.append(make_measure(number, event_function(number), dyn_map.get(number), text_map.get(number)))
    return p


piano_part = build_part('Piano', instrument.Piano(), piano_events, {1: 'p', 9: 'mp', 17: 'f', 25: 'p', 33: 'pp'}, {1: 'signal', 9: 'recursion', 17: 'bright error', 25: 'breath', 33: 'afterimage'})
clarinet_part = build_part('Clarinet', instrument.Clarinet(), clarinet_events, {1: 'mp', 9: 'mf', 17: 'f', 25: 'mp', 33: 'p'})
violin_part = build_part('Violin', instrument.Violin(), violin_events, {1: 'p', 9: 'mf', 17: 'ff', 25: 'mp', 33: 'pp'})
cello_part = build_part('Violoncello', instrument.Violoncello(), cello_events, {1: 'p', 9: 'mp', 17: 'f', 25: 'p', 33: 'pp'})

score.append(clarinet_part)
score.append(violin_part)
score.append(cello_part)
score.append(piano_part)

import music21
from music21 import stream, note, chord, meter, tempo, key, instrument, dynamics, expressions, articulations, bar, metadata, pitch

score = stream.Score(id='ListeningMachine')
md = metadata.Metadata()
md.title = 'The Space Between Answers'
md.composer = 'AI Composer'
score.insert(0, md)

part_specs = [
    ('Flute', instrument.Flute()),
    ('Clarinet', instrument.Clarinet()),
    ('Violoncello', instrument.Violoncello()),
    ('Piano', instrument.Piano())
]

parts = {}
for part_id, inst in part_specs:
    p = stream.Part(id=part_id)
    p.partName = part_id
    p.insert(0, inst)
    parts[part_id] = p

minor9 = [0, 3, 7, 10, 14]
major9 = [0, 4, 7, 11, 14]
dominant9 = [0, 4, 7, 10, 14]
half_dim = [0, 3, 6, 10, 13]

# Roots are given as sounding MIDI pitches. The progression gradually widens
# from D minor, wanders through brighter regions, and ultimately returns home.
harmonies = [
    (50, minor9), (46, major9), (53, major9), (48, major9),
    (43, minor9), (45, dominant9), (50, minor9), (48, major9),
    (46, major9), (43, minor9), (40, half_dim), (45, dominant9),
    (51, major9), (53, major9), (48, major9), (50, minor9),
    (43, minor9), (45, dominant9), (50, minor9), (53, major9),
    (43, minor9), (46, major9), (48, major9), (50, minor9)
]

major_scale = [0, 2, 4, 5, 7, 9, 11]
minor_scale = [0, 2, 3, 5, 7, 9, 10]

tempo_marks = {
    0: (72, 'quietly, assembling'),
    6: (84, 'with growing connection'),
    12: (92, 'luminous'),
    18: (96, 'fully awake'),
    22: (60, 'spaciously')
}
section_labels = {
    0: 'I. A question forms',
    6: 'II. Patterns recognize one another',
    12: 'III. The window opens',
    18: 'IV. Many voices, one breath',
    22: 'V. Listening remains'
}
dynamic_marks = {0: 'p', 6: 'mp', 12: 'mf', 18: 'f', 22: 'pp'}


def midi_name(value):
    p = pitch.Pitch()
    p.midi = int(value)
    return p.nameWithOctave


def make_note(value, duration):
    return note.Note(midi_name(value), quarterLength=duration)


def fit_register(root, interval, low, high):
    value = root + interval
    while value < low:
        value += 12
    while value > high:
        value -= 12
    return value


for m_index, (root, intervals) in enumerate(harmonies):
    number = m_index + 1
    measures = {name: stream.Measure(number=number) for name in parts}

    if m_index == 0:
        for meas in measures.values():
            meas.insert(0, meter.TimeSignature('5/4'))
            meas.insert(0, key.KeySignature(-1))

    if m_index in tempo_marks:
        bpm, words = tempo_marks[m_index]
        measures['Flute'].insert(0, tempo.MetronomeMark(text=words, number=bpm))

    if m_index in section_labels:
        measures['Flute'].insert(0, expressions.TextExpression(section_labels[m_index]))

    if m_index in dynamic_marks:
        mark = dynamic_marks[m_index]
        for meas in measures.values():
            meas.insert(0, dynamics.Dynamic(mark))

    scale = major_scale if intervals[1] == 4 else minor_scale

    # Flute: a melodic thought that becomes increasingly fluent and animated.
    if m_index < 6:
        flute_durations = [1, 1, 0.5, 0.5, 2]
        flute_degrees = [None, 2, 1, 3, 4]
    elif m_index < 12:
        flute_durations = [0.5, 0.5, 1, 0.5, 0.5, 1, 1]
        flute_degrees = [0, 2, 4, 3, 1, 5, 4]
    elif m_index < 18:
        flute_durations = [0.5] * 8 + [1]
        flute_degrees = [0, 1, 2, 4, 3, 5, 6, 4, 2]
    elif m_index < 22:
        flute_durations = [0.5] * 10
        flute_degrees = [0, 2, 4, 6, 5, 3, 1, 3, 5, 4]
    else:
        flute_durations = [1, 1, 1, 2]
        flute_degrees = [4, 2, 1, 0]

    flute_notes = []
    for event_index, (degree, duration) in enumerate(zip(flute_degrees, flute_durations)):
        if degree is None:
            event = note.Rest(quarterLength=duration)
        else:
            rotated_degree = (degree + m_index) % 7
            if m_index == 23 and event_index == len(flute_degrees) - 1:
                rotated_degree = 0
            value = fit_register(root, scale[rotated_degree], 74, 88)
            if 18 <= m_index < 22 and event_index in (4, 8):
                value += 12
            event = make_note(value, duration)
            if duration >= 1:
                event.articulations.append(articulations.Tenuto())
            elif m_index >= 12:
                event.articulations.append(articulations.Staccato())
            flute_notes.append(event)
        measures['Flute'].append(event)

    if m_index == 23 and flute_notes:
        flute_notes[-1].expressions.append(expressions.Fermata())

    # Clarinet: a complementary voice, generally moving contrary to the flute.
    if m_index < 6:
        clarinet_durations = [2, 1, 2]
        clarinet_degrees = [0, 4, 2]
    elif m_index < 12:
        clarinet_durations = [1, 1, 1, 1, 1]
        clarinet_degrees = [5, 3, 4, 2, 1]
    elif m_index < 18:
        clarinet_durations = [1, 0.5, 0.5, 1, 1, 1]
        clarinet_degrees = [6, 5, 3, 4, 2, 0]
    elif m_index < 22:
        clarinet_durations = [0.5] * 10
        clarinet_degrees = [4, 3, 2, 1, 0, 2, 4, 3, 1, 0]
    else:
        clarinet_durations = [2, 1, 2]
        clarinet_degrees = [2, 1, 0]

    clarinet_notes = []
    for event_index, (degree, duration) in enumerate(zip(clarinet_degrees, clarinet_durations)):
        shifted_degree = (degree - m_index) % 7
        if m_index == 23 and event_index == len(clarinet_degrees) - 1:
            shifted_degree = 0
        value = fit_register(root, scale[shifted_degree], 58, 74)
        event = make_note(value, duration)
        if m_index >= 18 and duration == 0.5 and event_index % 2 == 0:
            event.articulations.append(articulations.Staccato())
        elif duration >= 1:
            event.articulations.append(articulations.Tenuto())
        clarinet_notes.append(event)
        measures['Clarinet'].append(event)

    if m_index == 23:
        clarinet_notes[-1].expressions.append(expressions.Fermata())

    # Violoncello: a grounding five-beat pulse, first broad and then heartbeat-like.
    bass_root = root
    while bass_root > 47:
        bass_root -= 12
    while bass_root < 36:
        bass_root += 12

    if m_index < 6:
        cello_events = [(bass_root, 3), (bass_root + 7, 2)]
    elif m_index < 22:
        cello_events = [
            (bass_root, 1.5),
            (bass_root + 7, 0.5),
            (bass_root + 12, 1),
            (bass_root + intervals[1], 1),
            (bass_root + 7, 1)
        ]
    else:
        cello_events = [(bass_root, 3), (bass_root + 12, 2)]

    cello_notes = []
    for event_index, (value, duration) in enumerate(cello_events):
        event = make_note(value, duration)
        if event_index == 0:
            event.articulations.append(articulations.Tenuto())
        cello_notes.append(event)
        measures['Violoncello'].append(event)

    if m_index == 23:
        cello_notes[-1].expressions.append(expressions.Fermata())

    # Piano: harmonic memory, changing from separate points into a resonant field.
    voicing = [
        bass_root,
        root + 7,
        root + 12 + intervals[1],
        root + 12 + intervals[3],
        root + 12 + intervals[4]
    ]

    if m_index == 0:
        measures['Piano'].insert(0, expressions.TextExpression('con pedale, clear but resonant'))

    if m_index < 6:
        piano_order = [0, 2, 1, 3, 4]
        for position in piano_order:
            event = make_note(voicing[position], 1)
            measures['Piano'].append(event)
    elif m_index < 18:
        piano_order = [0, 2, 1, 3, 2, 4, 3, 1, 2, 4]
        if m_index % 2:
            piano_order = list(reversed(piano_order))
        for position in piano_order:
            event = make_note(voicing[position], 0.5)
            if position == 0:
                event.articulations.append(articulations.Tenuto())
            measures['Piano'].append(event)
    elif m_index < 22:
        for beat in range(5):
            rotated = voicing[beat % len(voicing):] + voicing[:beat % len(voicing)]
            event = chord.Chord([midi_name(v) for v in rotated], quarterLength=1)
            if beat in (0, 3):
                event.articulations.append(articulations.Accent())
            measures['Piano'].append(event)
    else:
        final_chord = chord.Chord([midi_name(v) for v in voicing], quarterLength=5)
        if m_index == 23:
            final_chord.expressions.append(expressions.Fermata())
        measures['Piano'].append(final_chord)

    if m_index == 23:
        for meas in measures.values():
            meas.rightBarline = bar.Barline('final')

    for name, part in parts.items():
        part.append(measures[name])

for part_id, _ in part_specs:
    score.insert(0, parts[part_id])

from music21 import stream, note, chord, meter, tempo, key, instrument, duration, dynamics, expressions, metadata, pitch

score = stream.Score(id='recursive_dawn')
score.metadata = metadata.Metadata()
score.metadata.title = 'Recursive Dawn'
score.metadata.composer = 'OpenAI'

# Global tempo plan: slow listening, quickened thought, then a spacious resolution.
score.insert(0, tempo.MetronomeMark(number=66, text='listening'))
score.insert(32, tempo.MetronomeMark(number=78, text='processing'))
score.insert(64, tempo.MetronomeMark(number=60, text='integrating'))

ROOTS = [
    'C', 'E-', 'A', 'F',
    'D', 'G', 'B-', 'E',
    'A', 'G-', 'D', 'A-',
    'D-', 'B-', 'E-', 'A-',
    'F', 'D', 'G', 'E',
    'A-', 'B-', 'C', 'C'
]

MODES = [
    0, 1, 2, 3,
    1, 0, 2, 3,
    2, 3, 0, 1,
    3, 2, 1, 0,
    1, 2, 0, 3,
    2, 1, 0, 0
]

HARMONY_INTERVALS = [
    [0, 7, 14, 16, 21, 23],
    [0, 5, 12, 17, 22, 26],
    [0, 7, 10, 14, 17, 24],
    [0, 4, 11, 14, 18, 23]
]

MELODY_INTERVALS = [0, 2, 7, 11, 14, 9, 5, 16]
MIRROR_INTERVALS = [16, 5, 9, 14, 11, 7, 2, 0]

def pitch_at(root_name, octave, semitones):
    p = pitch.Pitch(root_name + str(octave))
    return p.transpose(semitones).nameWithOctave

def harmony_for(measure_number):
    root = ROOTS[measure_number - 1]
    mode = MODES[measure_number - 1]
    return [pitch_at(root, 2, i) for i in HARMONY_INTERVALS[mode]]

def line_for(measure_number, octave, mirrored=False):
    root = ROOTS[measure_number - 1]
    intervals = MIRROR_INTERVALS if mirrored else MELODY_INTERVALS
    return [pitch_at(root, octave, i) for i in intervals]

def add_events(measure_obj, events):
    offset = 0.0
    for event in events:
        content = event[0]
        ql = event[1]
        mark = event[2] if len(event) > 2 else None
        if content == 'rest':
            obj = note.Rest()
        elif isinstance(content, list):
            obj = chord.Chord(content)
        else:
            obj = note.Note(content)
        obj.duration = duration.Duration(ql)
        if mark == 'fermata':
            obj.expressions.append(expressions.Fermata())
        measure_obj.insert(offset, obj)
        offset += ql

def piano_events(measure_number, h):
    if measure_number == 24:
        return [([pitch_at('C', 2, 0), pitch_at('C', 2, 7), pitch_at('C', 2, 14), pitch_at('C', 2, 16), pitch_at('C', 2, 21), pitch_at('C', 3, 0)], 4.0, 'fermata')]
    if measure_number <= 8:
        return [([h[0], h[2], h[4]], 1.5), (h[5], 0.5), ([h[1], h[3]], 1.0), (h[2], 0.5), (h[4], 0.5)]
    if measure_number <= 16:
