def pch(midi_number):
    p = pitch.Pitch()
    p.midi = int(max(0, min(127, midi_number)))
    return p

def n(midi_number, ql, art=None):
    x = note.Note()
    x.pitch = pch(midi_number)
    x.duration.quarterLength = ql
    if art == 'staccato':
        x.articulations.append(articulations.Staccato())
    elif art == 'tenuto':
        x.articulations.append(articulations.Tenuto())
    elif art == 'accent':
        x.articulations.append(articulations.Accent())
    return x

def r(ql):
    x = note.Rest()
    x.duration.quarterLength = ql
    return x

def ch(midi_numbers, ql, art=None):
    x = chord.Chord()
    x.pitches = [pch(m) for m in midi_numbers]
    x.duration.quarterLength = ql
    if art == 'staccato':
        x.articulations.append(articulations.Staccato())
    elif art == 'tenuto':
        x.articulations.append(articulations.Tenuto())
    elif art == 'accent':
        x.articulations.append(articulations.Accent())
    return x

def base_measure(number, dyn=None, text=None):
    m = stream.Measure(number=number)
    if number == 1:
        m.insert(0, meter.TimeSignature('5/4'))
        m.insert(0, key.KeySignature(0))
    if dyn is not None:
        m.insert(0, dynamics.Dynamic(dyn))
    if text is not None:
        tx = expressions.TextExpression(text)
        tx.placement = 'above'
        m.insert(0, tx)
    return m

def piano_measure(number, root):
    dyn = {1: 'mp', 9: 'mf', 17: 'f', 23: 'mp', 24: 'pp'}.get(number)
    text = {1: 'like a machine learning to breathe', 9: 'cantabile, spacious', 17: 'crystalline', 23: 'gently decelerating inside'}.get(number)
    m = base_measure(number, dyn, text)
    if number == 24:
        m.append(ch([33, 45, 52, 57, 64, 69, 76], 5, 'tenuto'))
    elif number <= 8:
        pattern = [root, root + 7, root + 14, root + 21, root + 28,
                   root + 26, root + 21, root + 16, root + 12, root + 7]
        for i, midi_number in enumerate(pattern):
            m.append(n(midi_number, 0.5, 'accent' if i == 0 else None))
    elif number <= 16:
        low = root - 12 if root - 12 >= 33 else root
        m.append(ch([low, root, root + 7, root + 16, root + 24], 2, 'tenuto'))
        for midi_number in [root + 19, root + 23, root + 26, root + 31]:
