        for interval, dur in zip(ints, durs):
            m.append(n(root + interval, dur, 'tenuto'))
    else:
        ints = [24, 26, 31, 33, 38, 40, 38, 35]
        durs = [0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 1, 1]
