    return m

def clarinet_measure(number, root):
    dyn = {1: 'p', 9: 'mp', 17: 'mf', 23: 'p', 24: 'pp'}.get(number)
    text = {1: 'answering fragments', 17: 'clear and quick'}.get(number)
