# A small vocabulary of cells: question, answer, pulse, breath.
question = [('G4', .5), ('A4', .5), ('Bb4', 1.0), ('D5', 1.0), ('C5', 1.0)]
answer = [('F5', .5), ('Eb5', .5), ('D5', 1.0), ('Bb4', 1.0), ('G4', 1.0)]
