def n(pitch, qlen):
    if pitch == 'rest':
        return note.Rest(quarterLength=qlen)
    return note.Note(pitch, quarterLength=qlen)

def put(part, events, dyn=None, stacc=False):
    for pit, dur in events:
        x = n(pit, dur)
        if dyn:
            x.expressions.append(dynamics.Dynamic(dyn))
            dyn = None
        if stacc and isinstance(x, note.Note):
            x.articulations.append(articulations.Staccato())
        part.append(x)

def bar_rest(part):
    part.append(note.Rest(quarterLength=4.0))

