    left = piano_bass[b % 4]
    right = piano_mid[(b + (1 if b >= 16 else 0)) % 4]
    piano.append(chord.Chord(list(left), quarterLength=2.0))
    c = chord.Chord(list(right), quarterLength=2.0)
    if b in (11, 19, 27, 34):
