    else:
        put(viola, [('rest', 1.0), ('Bb3', 1.0), ('D4', 1.0), ('F4', 1.0)], dyn='p')

# Flute: high weather-system; sparse at first, almost vocal by the end.
for b in range(36):
    if b < 2:
        bar_rest(flute)
    elif b < 8:
        put(flute, question if b % 2 == 0 else answer, dyn='p')
    elif b < 16:
        put(flute, climb if b % 2 == 0 else [('F5',1.0),('Eb5',1.0),('D5',1.0),('C5',.5),('Bb4',.5)], dyn='mp')
    elif b < 24:
