            put(flute, [('A5', .5), ('G5', .5), ('F5', 1.0), ('Eb5', 2.0)], dyn='mf')
        else:
            put(flute, [('rest',1.0),('D6',.5),('C6',.5),('Bb5',1.0),('A5',1.0)], dyn='mf')
    elif b < 28:
        put(flute, [('rest',2.0), ('G5',1.0), ('F5',1.0)], dyn='p')
    else:
        seq = [('Bb5',.5),('A5',.5),('G5',1.0),('F5',1.0),('D5',1.0)] if b < 33 else answer
        put(flute, seq, dyn='pp')

# Clarinet: the interior voice, mostly in chalumeau; transposition handled by instrument object.
for b in range(36):
