    else:
        put(clarinet, question if b % 2 else [('G4',2.0),('F4',1.0),('D4',1.0)], dyn='pp')

# Violin: surface glitter and argument; inverted motive at climax, long line at close.
for b in range(36):
    if b < 4:
        bar_rest(violin)
    elif b < 8:
        put(violin, [('D5',.5),('C5',.5),('Bb4',1.0),('A4',1.0),('G4',1.0)], dyn='mp')
