    elif b < 24:
        put(violin, [('Bb5',.5),('A5',.5),('G5',.5),('F5',.5),('Eb5',1.0),('D5',1.0)] if b%2 else [('F5',1.5),('G5',.5),('A5',1.0),('Bb5',1.0)], dyn='f')
