harmonies = A + B + C + D + E

quality_intervals = {
    'maj': [0, 4, 7, 11],
    'min': [0, 3, 7, 10],
    'sus': [0, 2, 7, 10],
    'dim': [0, 3, 6, 9]
}

dynamic_marks = {
    1: 'pp', 9: 'mp', 17: 'mf', 25: 'f', 33: 'p',
    41: 'pp', 49: 'mf', 57: 'ff', 61: 'p', 64: 'ppp'
}
