def make_note(midi_value, duration):
    n = note.Note()
    n.pitch.midi = int(midi_value)
    n.duration.quarterLength = duration
    return n


def make_chord(midi_values, duration):
    c = chord.Chord([int(x) for x in midi_values])
    c.duration.quarterLength = duration
    return c


def decorate_measure(m, measure_number, include_label=False):
    if measure_number == 1:
        m.insert(0, meter.TimeSignature('4/4'))
    if measure_number in key_changes:
        m.insert(0, key.KeySignature(key_changes[measure_number]))
    if measure_number in dynamic_marks:
        m.insert(0, dynamics.Dynamic(dynamic_marks[measure_number]))
    if include_label and measure_number in section_labels:
        text = expressions.TextExpression(section_labels[measure_number])
        text.style.fontStyle = 'italic'
        m.insert(0, text)


def finish_measure(m, measure_number):
    if measure_number == 64:
        sounding = list(m.recurse().notes)
        if sounding:
            sounding[-1].expressions.append(expressions.Fermata())
        m.rightBarline = bar.Barline('final')


def add_line(m, pitches, durations, character='plain'):
    for i, (pitch_value, duration) in enumerate(zip(pitches, durations)):
        if pitch_value is None:
            obj = note.Rest(quarterLength=duration)
        else:
            obj = make_note(pitch_value, duration)
            if character == 'searching' and i % 4 == 0:
                obj.articulations.append(articulations.Tenuto())
            elif character == 'machine':
                if i % 4 == 0:
                    obj.articulations.append(articulations.Accent())
                else:
                    obj.articulations.append(articulations.Staccato())
            elif character == 'suspended':
                obj.articulations.append(articulations.Tenuto())
            elif character == 'urgent' and i % 2 == 0:
                obj.articulations.append(articulations.Accent())
        m.append(obj)


def build_violin():
    part = stream.Part(id='Violin')
    part.partName = 'Violin'
    part.insert(0, instrument.Violin())
    motif_a = [7, 10, 12, 15, 14, 12, 10, 7]
    motif_b = [3, 7, 10, 12, 10, 8, 7, 3]
    rapid = [7, 10, 12, 15, 14, 12, 10, 7, 8, 10, 14, 17, 15, 14, 10, 7]
    for b, (root, quality) in enumerate(harmonies, start=1):
        m = stream.Measure(number=b)
        decorate_measure(m, b, include_label=True)
        if b <= 16:
            motif = motif_a if b % 2 else motif_b
            pitches = [root + 24 + x for x in motif]
            add_line(m, pitches, [0.5] * 8, 'searching')
        elif b <= 32:
            turn = (b - 17) % 4
            pitches = [root + 24 + x + (2 if turn == 2 else 0) for x in rapid]
            if turn == 3:
                pitches = list(reversed(pitches))
            add_line(m, pitches, [0.25] * 16, 'machine')
        elif b <= 48:
            ints = quality_intervals[quality]
            pitches = [root + 31, root + 24 + ints[1], root + 26]
            add_line(m, pitches, [2.0, 1.0, 1.0], 'suspended')
        elif b <= 60:
            pattern = [12, 15, 19, 17, 15, 12, 10, 7]
            if b % 2 == 0:
                pattern = [19, 17, 15, 12, 10, 12, 14, 15]
            add_line(m, [root + 24 + x for x in pattern], [0.5] * 8, 'urgent')
        else:
            if b == 61:
                add_line(m, [root + 31, root + 28, root + 27, root + 24], [1.0] * 4, 'suspended')
            elif b == 62:
                add_line(m, [root + 31, root + 27], [2.0, 2.0], 'suspended')
            elif b == 63:
                add_line(m, [root + 26, root + 27, root + 31], [1.0, 1.0, 2.0], 'suspended')
            else:
                add_line(m, [root + 26], [4.0], 'suspended')
        finish_measure(m, b)
        part.append(m)
    return part


def build_viola():
    part = stream.Part(id='Viola')
    part.partName = 'Viola'
    part.insert(0, instrument.Viola())
    for b, (root, quality) in enumerate(harmonies, start=1):
        m = stream.Measure(number=b)
        decorate_measure(m, b)
        ints = quality_intervals[quality]
        if b <= 16:
            pitches = [root + 12 + ints[1], root + 19, root + 12 + ints[2], root + 14]
            add_line(m, pitches, [1.0] * 4, 'searching')
        elif b <= 32:
            pattern = [ints[1], 7, 10, 7, ints[1], 2, 7, 10]
            add_line(m, [root + 12 + x for x in pattern], [0.5] * 8, 'machine')
        elif b <= 48:
            add_line(m, [root + 12 + ints[1], root + 19], [2.0, 2.0], 'suspended')
        elif b <= 60:
            pattern = [ints[1], 7, 10, 7, ints[1], 2]
            add_line(m, [root + 12 + x for x in pattern], [0.5, 1.0, 0.5, 0.5, 1.0, 0.5], 'urgent')
        else:
            if b == 64:
                add_line(m, [root + 15], [4.0], 'suspended')
            else:
                add_line(m, [root + 12 + ints[1]], [4.0], 'suspended')
        finish_measure(m, b)
        part.append(m)
    return part


def build_cello():
    part = stream.Part(id='Cello')
    part.partName = 'Violoncello'
    part.insert(0, instrument.Violoncello())
    for b, (root, quality) in enumerate(harmonies, start=1):
        m = stream.Measure(number=b)
        decorate_measure(m, b)
        if b <= 16:
            add_line(m, [root, root + 7], [2.0, 2.0], 'suspended')
        elif b <= 32:
            add_line(m, [root, root + 7, root + 12, root + 7], [1.0] * 4, 'machine')
        elif b <= 48:
            add_line(m, [root], [4.0], 'suspended')
        elif b <= 60:
            add_line(m, [root, root + 7, root + 12, root + 7, root, root + 7, root + 10, root + 7], [0.5] * 8, 'urgent')
        else:
            add_line(m, [root], [4.0], 'suspended')
        finish_measure(m, b)
        part.append(m)
    return part


def build_piano_right():
    part = stream.Part(id='PianoRH')
    part.partName = 'Piano, right hand'
    part.insert(0, instrument.Piano())
    for b, (root, quality) in enumerate(harmonies, start=1):
        m = stream.Measure(number=b)
        decorate_measure(m, b)
        ints = quality_intervals[quality]
        tones = [root + 24 + x for x in ints]
        if b <= 16:
            pattern = [tones[0], tones[1], tones[2], tones[3], tones[2], tones[1], root + 26, tones[1]]
            add_line(m, pattern, [0.5] * 8, 'searching')
        elif b <= 32:
            pattern = [tones[i % 4] + (12 if i in (3, 7, 11, 15) else 0) for i in range(16)]
            add_line(m, pattern, [0.25] * 16, 'machine')
        elif b <= 48:
            c1 = make_chord(tones[:3], 2.0)
            c2 = make_chord([tones[1], tones[2], tones[3], root + 38], 2.0)
            c1.articulations.append(articulations.Tenuto())
            c2.articulations.append(articulations.Tenuto())
            m.append(c1)
            m.append(c2)
        elif b <= 60:
            for i in range(8):
                if i % 2 == 0:
                    obj = make_chord([tones[0], tones[1], tones[2]], 0.5)
                    obj.articulations.append(articulations.Accent())
                else:
                    obj = make_note(tones[(i // 2) % 4] + 12, 0.5)
                    obj.articulations.append(articulations.Staccato())
                m.append(obj)
        else:
            if b == 61:
                m.append(make_chord([tones[0], tones[1], tones[2]], 2.0))
                m.append(note.Rest(quarterLength=1.0))
                m.append(make_note(root + 26, 1.0))
            elif b == 62:
                m.append(make_chord([tones[0], tones[2], tones[3]], 4.0))
            elif b == 63:
                m.append(note.Rest(quarterLength=1.0))
                m.append(make_chord([tones[0], tones[1], tones[2]], 3.0))
            else:
                m.append(make_chord([root + 24, root + 27, root + 31, root + 38], 4.0))
        finish_measure(m, b)
        part.append(m)
    return part


def build_piano_left():
    part = stream.Part(id='PianoLH')
    part.partName = 'Piano, left hand'
    part.insert(0, instrument.Piano())
    for b, (root, quality) in enumerate(harmonies, start=1):
        m = stream.Measure(number=b)
        decorate_measure(m, b)
        if b <= 16:
            m.append(make_chord([root, root + 12], 2.0))
            m.append(make_chord([root + 7, root + 19], 2.0))
        elif b <= 32:
            for p in [root, root + 7, root + 12, root + 7]:
                c = make_chord([p, p + 12], 1.0)
                c.articulations.append(articulations.Staccato())
                m.append(c)
        elif b <= 48:
            c = make_chord([root, root + 12], 4.0)
            c.articulations.append(articulations.Tenuto())
            m.append(c)
        elif b <= 60:
            for p in [root, root + 7, root + 12, root + 7, root, root + 7, root + 10, root + 7]:
                m.append(make_note(p, 0.5))
        else:
            m.append(make_chord([root, root + 12], 4.0))
        finish_measure(m, b)
        part.append(m)
    return part


violin_part = build_violin()
viola_part = build_viola()
cello_part = build_cello()
