# Helper to make sustained chords
def make_chord(pitches, ql):
    c = chord.Chord(pitches)
    c.duration = duration.Duration(ql)
    return c

# Helper to make a note
def make_note(pitch, ql, dyn=None):
    n = note.Note(pitch)
    n.duration = duration.Duration(ql)
    if dyn is not None:
        n.volume.velocity = dyn
    return n

