# Motive A: questioning, stepwise ascent then fall (used in violin)
def motive_a(start_pitch='E5', ql=0.5):
    s = stream.Voice()
    pitches = [start_pitch, 'F#5', 'G5', 'B5', 'A5', 'G5']
    for p in pitches:
