def piano_ostinato(pattern_root='E3', ql=0.5):
    s = stream.Voice()
    # pattern: root - 5th - 9th - 3rd
    ost_pitches = [pattern_root, None, None, None]
    # map to absolute pitches based on root
    if pattern_root.startswith('E'):
        ost_pitches = ['E3', 'B3', 'F#4', 'G4']
    elif pattern_root.startswith('C'):
        ost_pitches = ['C3', 'G3', 'D4', 'E4']
    elif pattern_root.startswith('A'):
        ost_pitches = ['A2', 'E3', 'B3', 'C4']
    elif pattern_root.startswith('G'):
        ost_pitches = ['G2', 'D3', 'A3', 'B3']
    else:
        ost_pitches = [pattern_root, pattern_root, pattern_root, pattern_root]
    for p in ost_pitches:
        s.append(make_note(p, ql))
    return s

# SECTION A – Introspective, sparse (~24 measures)
for m in range(1, 25):
    meas_p = stream.Measure(number=m)
    meas_v = stream.Measure(number=m)
    meas_c = stream.Measure(number=m)

    # Piano: slow evolving chords in E minor with added tones
    if m <= 8:
        # Establish E minor space
        if m % 2 == 1:
            meas_p.append(make_chord(['E3', 'B3', 'E4', 'G4'], 4.0))
        else:
            meas_p.append(make_chord(['D3', 'A3', 'D4', 'F#4'], 4.0))
    elif m <= 16:
        # Slight harmonic motion
        if m % 4 == 1:
            meas_p.append(make_chord(['C3', 'G3', 'C4', 'E4'], 4.0))
        elif m % 4 == 2:
            meas_p.append(make_chord(['A2', 'E3', 'A3', 'C4'], 4.0))
        elif m % 4 == 3:
            meas_p.append(make_chord(['F#2', 'C#3', 'E3', 'A3'], 4.0))
        else:
            meas_p.append(make_chord(['E3', 'B3', 'E4', 'G4'], 4.0))
    else:
        # Return toward E, with suspensions
        if m % 2 == 1:
            meas_p.append(make_chord(['E3', 'B3', 'F#4', 'A4'], 4.0))
        else:
            meas_p.append(make_chord(['E3', 'B3', 'E4', 'G4'], 4.0))

    # Violin: enters gradually with fragments of motive A
    if 5 <= m <= 20:
        if m % 4 in (1, 2):
            # place motive A in upper register sparsely
            v_voice = motive_a('E5', ql=0.5)
            meas_v.append(v_voice)
        else:
            # more rests, a single long tone
            if m % 4 == 3:
                meas_v.append(make_note('B4', 2.0))
                meas_v.append(note.Rest(quarterLength=2.0))
            else:
                meas_v.append(note.Rest(quarterLength=4.0))
    else:
        meas_v.append(note.Rest(quarterLength=4.0))

    # Clarinet: very sparse, shadowing violin intervals lower
    if 9 <= m <= 20 and m % 4 == 2:
        c_voice = motive_b('B3', ql=0.5)
        meas_c.append(c_voice)
    else:
        meas_c.append(note.Rest(quarterLength=4.0))

    piano_part.append(meas_p)
    violin_part.append(meas_v)
    clarinet_part.append(meas_c)

# SECTION B – More active, ostinati and interplay (~24 measures)
for m in range(25, 49):
    meas_p = stream.Measure(number=m)
    meas_v = stream.Measure(number=m)
    meas_c = stream.Measure(number=m)

    # Piano: alternating ostinati over shifting roots
    if m % 8 in (1, 2, 3, 4):
        root = 'E3'
    elif m % 8 in (5, 6):
        root = 'C3'
    else:
        root = 'A2'

    ost_voice = stream.Voice()
    # Each measure: 2 repetitions of 4 eighth-notes pattern
    for _ in range(2):
        ost_voice.append(piano_ostinato(root, ql=0.5))
    meas_p.append(ost_voice)

    # Violin: develops motive A, sequencing and extension
    if m % 4 == 1:
        v1 = motive_a('G5', ql=0.5)
        meas_v.append(v1)
    elif m % 4 == 2:
        v2 = motive_a('B5', ql=0.5)
        meas_v.append(v2)
    elif m % 4 == 3:
        # Variation: invert contour
        v_voice = stream.Voice()
        pitches = ['B5', 'A5', 'G5', 'E5', 'F#5', 'G5']
        for p in pitches:
            v_voice.append(make_note(p, 0.5))
        meas_v.append(v_voice)
    else:
        # Long held note over motion
        meas_v.append(make_note('E6', 4.0))

    # Clarinet: rhythmic counter-motive B
    if m % 3 == 0:
        c_voice = motive_b('E4', ql=0.5)
        meas_c.append(c_voice)
    elif m % 3 == 1:
        c_voice = motive_b('G4', ql=0.5)
        meas_c.append(c_voice)
    else:
        # two short figures then a rest
        c_voice = stream.Voice()
        c_voice.append(motive_b('B3', ql=0.25))
        c_voice.append(motive_b('D4', ql=0.25))
        meas_c.append(c_voice)

    piano_part.append(meas_p)
    violin_part.append(meas_v)
    clarinet_part.append(meas_c)

# SECTION C – Quiet resolution / coda (~16 measures)
for m in range(49, 65):
    meas_p = stream.Measure(number=m)
    meas_v = stream.Measure(number=m)
    meas_c = stream.Measure(number=m)

    # Piano: gradually lengthening chords, thinning texture
    if m < 57:
        if m % 4 == 1:
            meas_p.append(make_chord(['C3', 'G3', 'C4', 'E4'], 4.0))
        elif m % 4 == 2:
            meas_p.append(make_chord(['A2', 'E3', 'A3', 'C4'], 4.0))
        elif m % 4 == 3:
            meas_p.append(make_chord(['D3', 'A3', 'D4', 'F#4'], 4.0))
        else:
            meas_p.append(make_chord(['E3', 'B3', 'E4', 'G4'], 4.0))
    else:
        # last 8 measures: pedal E with gentle color changes
        if m % 2 == 1:
            meas_p.append(make_chord(['E3', 'B3', 'E4', 'A4'], 4.0))
        else:
            meas_p.append(make_chord(['E3', 'B3', 'E4', 'G4'], 4.0))

    # Violin: fragmented motive A in high register, then descent
    if m < 57:
        if m % 4 in (1, 2):
            v_frag = motive_a('E6', ql=0.5)
            meas_v.append(v_frag)
        else:
            meas_v.append(note.Rest(quarterLength=4.0))
    else:
        # gentle stepwise descent toward middle register
        v_voice = stream.Voice()
        pitches = ['E6', 'D6', 'C6', 'B5', 'A5', 'G5', 'F#5', 'E5']
        for p in pitches:
            v_voice.append(make_note(p, 0.5))
        meas_v.append(v_voice)

    # Clarinet: echoes and then supports final calm
    if m < 57:
        if m % 4 == 3:
            c_echo = motive_b('E4', ql=0.5)
            meas_c.append(c_echo)
        else:
            meas_c.append(note.Rest(quarterLength=4.0))
    else:
        # sustained tones forming simple counter-line
        if m % 2 == 1:
            meas_c.append(make_note('G4', 4.0))
        else:
            meas_c.append(make_note('B3', 4.0))

    piano_part.append(meas_p)
    violin_part.append(meas_v)
    clarinet_part.append(meas_c)

# Assemble score
score.append(piano_part)
score.append(violin_part)
score.append(clarinet_part)

