def get_cello_measure(meas_num, var_idx):
    m = music21.stream.Measure(number=meas_num)
    if meas_num == 1:
        m.append(music21.clef.BassClef())
        m.append(music21.key.KeySignature(0))
        m.append(music21.meter.TimeSignature('4/4'))

    step = (meas_num - 1) % 4

    if var_idx in [0, 1, 2]:
        if step == 0:
            m.append(music21.note.Note('C3', quarterLength=2.0))
