            m.append(music21.note.Note('G2', quarterLength=1.0))
            m.append(music21.note.Note('C3', quarterLength=2.0))

    elif var_idx in [3, 4, 5]:
        if step == 0:
            m.append(music21.note.Note('C3', quarterLength=1.0))
            m.append(music21.note.Note('E3', quarterLength=1.0))
            m.append(music21.note.Note('G2', quarterLength=1.0))
