            m.append(music21.note.Note('G2', quarterLength=1.0))
            m.append(music21.note.Note('C3', quarterLength=1.0))

    else:
        if step == 0:
            m.append(music21.note.Note('C2', quarterLength=2.0))
            m.append(music21.note.Note('G2', quarterLength=2.0))
        elif step == 1:
