def ev(kind, val, dur):
    return (kind, val, dur)

def bar_events(items):
    out = []
    off = 0.0
    for kind, val, dur in items:
        if kind == 'n':
            obj = note.Note(val)
        elif kind == 'c':
            obj = chord.Chord(val)
        else:
            obj = note.Rest()
        obj.quarterLength = dur
        out.append((off, obj))
        off += dur
    if abs(off - 4.0) > 0.0001:
        raise ValueError('bad bar')
    return out

def add_measure(part, number, events, dyn=None):
    m = stream.Measure(number=number)
    if dyn is not None:
        m.insert(0, dynamics.Dynamic(dyn))
    for off, obj in events:
        m.insert(off, obj)
    part.append(m)

