scale_steps = [('E', 0), ('F#', 0), ('G', 0), ('A', 0), ('B', 0), ('C#', 1), ('D', 1)]
roots = [0, 2, 3, 4, 5, 3, 1, 4, 0, 5, 2, 6, 3, 1, 4, 4, 0, 2, 5, 1, 6, 3, 4, 5, 0, 3, 5, 2, 1, 4, 0, 6, 5, 3, 1, 0]
assistant_degrees = [0, 4, 4, 1, 4, 5, 0, 6, 5]
violin_line = [7, 9, 11, 10, 12, 14, 13, 11, 9, 12, 16, 14, 13, 11, 10, 9, 7, 10, 15, 13, 16, 12, 14, 11, 9, 7, 6, 9, 11, 8, 7, 5, 4, 6, 8, 7]

def sp(degree, octave):
    shift, idx = divmod(degree, len(scale_steps))
    name, extra_octave = scale_steps[idx]
    return name + str(octave + shift + extra_octave)

def make_element(p, ql, part_name=None):
    if p is None:
        obj = note.Rest(quarterLength=ql)
    elif isinstance(p, (list, tuple)):
        obj = chord.Chord(list(p), quarterLength=ql)
    else:
        obj = note.Note(p, quarterLength=ql)
    if isinstance(obj, note.Note):
        if part_name in ('Clarinet', 'Flute') and ql <= 0.5:
            obj.articulations.append(articulations.Staccato())
        if part_name in ('Violin', 'Violoncello') and ql >= 2:
            obj.articulations.append(articulations.Tenuto())
    return obj

def make_measure(number, events, part_name=None, dyn=None, text=None, tempo_mark=None, setup=False, clef_obj=None):
    m = stream.Measure(number=number)
    if setup:
        m.insert(0, meter.TimeSignature('4/4'))
        m.insert(0, key.Key('E', 'minor'))
        if clef_obj is not None:
            m.insert(0, clef_obj)
    if tempo_mark is not None:
        m.insert(0, tempo.MetronomeMark(number=tempo_mark))
    if dyn is not None:
        m.insert(0, dynamics.Dynamic(dyn))
    if text is not None:
        tx = expressions.TextExpression(text)
        tx.placement = 'above'
        m.insert(0, tx)
    used = 0.0
    for p, ql in events:
        m.append(make_element(p, ql, part_name=part_name))
        used += float(ql)
    if used < 3.999:
        m.append(note.Rest(quarterLength=4.0 - used))
    if number == 36:
        last_items = list(m.notesAndRests)
        if last_items:
            last_items[-1].expressions.append(expressions.Fermata())
    return m

def piano_events(m):
    root = roots[m - 1]
    if m >= 33:
        return [([sp(root, 2), sp(root + 4, 3), sp(root + 1, 4), sp(root + 6, 4)], 2.0),
                ([sp(root, 2), sp(root + 2, 3), sp(root + 5, 4), sp(root + 1, 5)], 2.0)]
    pattern = [0, 4, 1, 6, 2, 5, 1, 4]
    events = []
    for j, off in enumerate(pattern):
        if j % 2 == 0:
            pitches = [sp(root, 2), sp(root + off, 3)]
            if j == 4:
                pitches.append(sp(root + 6, 4))
        else:
            pitches = [sp(root + off, 4), sp(root + off + 2, 5)]
        events.append((pitches, 0.5))
    return events

def cello_events(m):
    root = roots[m - 1]
    if m <= 8:
        return [(sp(root, 2), 4.0)]
    if m <= 16:
        return [(sp(root, 2), 3.0), (sp(roots[m % len(roots)], 2), 1.0)]
    if m <= 24:
        return [(sp(root, 2), 2.0), (sp(root + 4, 2), 1.0), (sp(root + 1, 2), 1.0)]
    if m <= 32:
        return [(sp(root, 2), 2.0), (sp(root - 1, 2), 2.0)]
    return [(sp(root, 2), 4.0)]

def violin_events(m):
    deg = violin_line[m - 1]
    if m <= 8:
        return [(sp(deg, 3), 3.0), (sp(deg + 1, 3), 1.0)]
    if m <= 16:
        return [(sp(deg, 3), 1.5), (sp(deg + 2, 3), 1.0), (sp(deg - 1, 3), 1.5)]
    if m <= 24:
        return [(sp(deg, 3), 1.0), (sp(deg + 3, 3), 0.5), (sp(deg + 1, 3), 0.5), (sp(deg - 2, 3), 2.0)]
    if m <= 32:
        return [(sp(deg, 3), 2.0), (sp(deg - 1, 3), 1.0), (sp(deg - 3, 3), 1.0)]
    return [(sp(deg, 3), 4.0)]

def clarinet_events(m):
    root = roots[m - 1]
    base = root + (m % 3)
    if m <= 8:
        return [(None, 1.0)] + [(sp(base + assistant_degrees[(m + j) % len(assistant_degrees)], 3), 0.5) for j in range(6)]
    if m <= 16:
        return [(sp(base + assistant_degrees[(m + j) % len(assistant_degrees)], 3), 0.5) for j in range(8)]
    if m <= 24:
        durations = [0.5, 0.5, 1.0, 0.5, 0.5, 1.0]
        return [(sp(base + assistant_degrees[(m + j * 2) % len(assistant_degrees)], 3), durations[j]) for j in range(6)]
    if m <= 32:
        return [(sp(base + 4, 3), 1.0), (None, 0.5), (sp(base + 1, 3), 0.5), (sp(base + 6, 3), 1.0), (None, 1.0)]
    return [(sp(base + assistant_degrees[m % len(assistant_degrees)], 3), 4.0)]

def flute_events(m):
    root = roots[m - 1]
    if m <= 8:
        if m % 2 == 0:
            return [(None, 2.0), (sp(root + 6, 5), 1.0), (sp(root + 5, 5), 1.0)]
        return [(None, 3.0), (sp(root + 6, 5), 1.0)]
    if m <= 16:
        return [(None, 0.5)] + [(sp(root + assistant_degrees[(m + j) % len(assistant_degrees)], 5), 0.5) for j in range(7)]
    if m <= 24:
        return [(sp(root + assistant_degrees[(m + j) % len(assistant_degrees)], 5), 0.25) for j in range(16)]
    if m <= 32:
        return [(sp(root + 6, 5), 1.5), (sp(root + 4, 5), 1.0), (sp(root + 1, 5), 1.5)]
    return [(sp(root + 6, 5), 4.0)]

