def section_shift_for_bar(bar):
    return [0, 1, 2, 0][(bar - 1) // 8]

def add_markers(measure, bar, primary=False):
    if bar == 1:
        measure.insert(0, meter.TimeSignature('4/4'))
        measure.insert(0, key.KeySignature(0))
        measure.insert(0, tempo.MetronomeMark(number=64))
    if bar == 9:
        measure.insert(0, key.KeySignature(-2))
    if bar == 17:
        measure.insert(0, key.KeySignature(2))
    if bar == 25:
        measure.insert(0, key.KeySignature(2))
    if bar == 29:
        measure.insert(0, tempo.MetronomeMark(number=56))
    dynamic_map = {1: 'p', 9: 'mp', 17: 'mf', 25: 'p', 29: 'pp'}
    if bar in dynamic_map:
        measure.insert(0, dynamics.Dynamic(dynamic_map[bar]))
    if primary:
        text_map = {1: 'quietly, almost spoken', 9: 'more outward', 17: 'restless brightness', 25: 'returning, clearer', 29: 'letting go'}
        if bar in text_map:
            measure.insert(0, expressions.TextExpression(text_map[bar]))

def add_note(measure, p, ql, art=None, fermata=False):
    if p is None:
        n = note.Rest(quarterLength=ql)
    else:
        n = note.Note(p, quarterLength=ql)
        if art == 'tenuto':
            n.articulations.append(articulations.Tenuto())
        elif art == 'staccato':
            n.articulations.append(articulations.Staccato())
        elif art == 'accent':
            n.articulations.append(articulations.Accent())
    if fermata:
        n.expressions.append(expressions.Fermata())
    measure.append(n)

def add_chord(measure, ps, ql, art=None, fermata=False):
    c = chord.Chord(ps, quarterLength=ql)
    if art == 'accent':
        c.articulations.append(articulations.Accent())
    if art == 'tenuto':
        c.articulations.append(articulations.Tenuto())
    if fermata:
        c.expressions.append(expressions.Fermata())
    measure.append(c)

def transpose_name(p, interval_name):
    return pitch.Pitch(p).transpose(interval_name).nameWithOctave

def build_clarinet():
    part = stream.Part(id='clarinet')
    part.partName = 'Clarinet'
    part.insert(0, instrument.Clarinet())
    for bar in range(1, 33):
        m = stream.Measure(number=bar)
        add_markers(m, bar, primary=True)
        mode = mode_for_bar(bar, high=False)
        if bar == 32:
            for degree, dur in zip([7, 6, 4, 0], [1.0, 1.0, 1.0, 1.0]):
                add_note(m, mode[degree], dur, art='tenuto')
        elif bar % 8 == 0:
            for degree, dur in zip([4, 3, 1, 0], [1.5, 0.5, 0.5, 1.5]):
                add_note(m, mode[degree], dur, art='tenuto' if dur >= 1.0 else None)
        else:
            degrees, durs = clarinet_patterns[(bar - 1) % 4]
            shift = section_shift_for_bar(bar)
            for degree, dur in zip(degrees, durs):
                if degree is None:
                    add_note(m, None, dur)
                else:
                    add_note(m, mode[degree + shift], dur, art='tenuto' if dur >= 1.0 else None)
        part.append(m)
    return part

def build_violin():
    part = stream.Part(id='violin')
    part.partName = 'Violin'
    part.insert(0, instrument.Violin())
    for bar in range(1, 33):
        m = stream.Measure(number=bar)
        add_markers(m, bar)
        mode = mode_for_bar(bar, high=True)
        if bar == 32:
            add_chord(m, ['A4', 'D5', 'F#5'], 4.0, art='tenuto', fermata=True)
        elif bar % 8 == 0:
            for degree, dur in zip([6, 5, 4], [1.5, 1.0, 1.5]):
                add_note(m, mode[degree], dur, art='tenuto')
        else:
            degrees, durs = violin_patterns[(bar - 1) % 4]
            shift = section_shift_for_bar(bar)
            for degree, dur in zip(degrees, durs):
                if degree is None:
                    add_note(m, None, dur)
                else:
                    add_note(m, mode[degree + shift], dur, art='tenuto' if dur >= 1.0 else None)
        part.append(m)
    return part

def build_piano():
    part = stream.Part(id='piano')
    part.partName = 'Piano'
    part.insert(0, instrument.Piano())
    for bar, harmony in enumerate(harmonies, start=1):
        m = stream.Measure(number=bar)
        add_markers(m, bar)
        if bar == 32:
            add_chord(m, harmony, 4.0, art='tenuto', fermata=True)
        elif bar in [8, 16, 24]:
            add_chord(m, harmony, 2.0, art='tenuto')
            add_note(m, None, 0.5)
            add_note(m, harmony[-1], 0.5)
            add_note(m, harmony[-2], 0.5)
            add_note(m, harmony[-1], 0.5)
        elif bar <= 8 or bar >= 25:
            pattern = [0, 1, 2, 3, 2, 1, 3, 2]
            for idx in pattern:
                add_note(m, harmony[idx % len(harmony)], 0.5)
        elif bar <= 16:
            add_chord(m, harmony, 1.5, art='tenuto')
            add_note(m, None, 0.5)
            add_chord(m, harmony[1:] + harmony[:1], 1.0)
            add_note(m, harmony[-1], 0.5)
            add_note(m, harmony[-2], 0.5)
        else:
            pattern = [0, 2, 1, 3, 0, 2, 1, 3]
            for i, idx in enumerate(pattern):
                add_note(m, harmony[idx % len(harmony)], 0.5, art='accent' if i in [0, 4] else None)
        part.append(m)
    return part

def build_cello():
    part = stream.Part(id='violoncello')
    part.partName = 'Violoncello'
    part.insert(0, instrument.Violoncello())
    for bar, root in enumerate(cello_roots, start=1):
        m = stream.Measure(number=bar)
        add_markers(m, bar)
        if bar == 32:
            add_note(m, 'D2', 4.0, art='tenuto', fermata=True)
        elif bar % 8 == 0:
            add_note(m, root, 4.0, art='tenuto')
        elif 17 <= bar <= 24:
            add_note(m, root, 1.0, art='accent')
            add_note(m, transpose_name(root, 'P5'), 1.0)
            add_note(m, transpose_name(root, 'P4'), 0.5)
            add_note(m, transpose_name(root, 'P5'), 0.5)
            add_note(m, root, 1.0, art='tenuto')
        else:
            add_note(m, root, 2.0, art='tenuto')
            add_note(m, transpose_name(root, 'P5'), 1.0)
            add_note(m, transpose_name(root, 'P8'), 1.0)
        part.append(m)
    return part

score.append(build_clarinet())
score.append(build_violin())
score.append(build_piano())
score.append(build_cello())

