def pick(seq, index):
    return seq[index % len(seq)]

def N(pitch_name, ql, accent=False, staccato=False):
    return ('n', pitch_name, ql, accent, staccato)

def R(ql):
    return ('r', None, ql, False, False)

def C(pitches, ql, accent=False, staccato=False):
    return ('c', pitches, ql, accent, staccato)

def append_item(meas, item):
    kind, data, ql, accent, staccato = item
    if kind == 'r':
        obj = note.Rest(quarterLength=ql)
    elif kind == 'c':
        obj = chord.Chord(data, quarterLength=ql)
    else:
        obj = note.Note(data, quarterLength=ql)
    if accent:
        obj.articulations.append(articulations.Accent())
    if staccato:
        obj.articulations.append(articulations.Staccato())
    meas.append(obj)

def make_measure(number, items, dynamic_mark=None, label=None):
    meas = stream.Measure(number=number)
    if number == 1:
        meas.append(meter.TimeSignature('4/4'))
        meas.append(key.Key('C'))
        meas.append(tempo.MetronomeMark(number=72, text='calm signal'))
    elif number == 9:
        meas.append(key.Key('E'))
    elif number == 17:
        meas.append(key.Key('B'))
        meas.append(tempo.MetronomeMark(number=84, text='bright inference'))
    elif number == 25:
        meas.append(key.Key('C'))
        meas.append(tempo.MetronomeMark(number=66, text='human return'))
    if dynamic_mark is not None:
        meas.insert(0, dynamics.Dynamic(dynamic_mark))
    if label is not None:
        meas.insert(0, expressions.TextExpression(label))
    total = sum(item[2] for item in items)
    for item in items:
        append_item(meas, item)
    if total < 4.0:
        append_item(meas, R(4.0 - total))
    return meas

def piano_items(number):
    h = harmonies[number - 1]
    if number <= 8:
        return [C([h[0], h[1]], 1.5), R(0.5), C(h[1:], 1.0), C([h[0], h[2], h[3], h[4]], 1.0)]
    if number <= 16:
        return [C([h[0], h[2], h[4]], 0.75, accent=True), R(0.25), C(h[1:4], 1.0), C([h[0], h[3], h[4]], 1.0), C(h, 1.0)]
    if number <= 24:
        seq = [h[0], h[1], h[2], h[3], h[4], h[3], h[2], h[1]]
        return [N(seq[j], 0.5, accent=(j in [0, 4]), staccato=(j % 2 == 1)) for j in range(8)]
    return [C(h, 2.0), R(0.5), C([h[1], h[2], h[3], h[4]], 1.5)]

def cello_items(number):
    h = harmonies[number - 1]
    if number <= 8:
        return [N(h[0], 3.0), N(h[1], 1.0)]
    if number <= 16:
        return [N(h[0], 2.0), N(h[1], 1.0), N(h[2], 1.0)]
    if number <= 24:
        return [N(h[0], 1.0, accent=True), N(h[1], 1.0), N(h[0], 1.5), R(0.5)]
    return [N(h[0], 4.0)]

def clarinet_items(number):
    if number <= 2:
        return [R(4.0)]
    idx = number - 3
    if number <= 8:
        return [R(1.0), N(pick(clarinet_pitches, idx), 1.5), N(pick(clarinet_pitches, idx + 2), 1.0), R(0.5)]
    if number <= 16:
        return [N(pick(clarinet_pitches, idx), 1.0), N(pick(clarinet_pitches, idx + 1), 1.0), R(0.5), N(pick(clarinet_pitches, idx + 3), 0.5, accent=True), N(pick(clarinet_pitches, idx + 2), 1.0)]
    if number <= 24:
        return [N(pick(clarinet_pitches, idx), 0.75), N(pick(clarinet_pitches, idx + 2), 0.75), N(pick(clarinet_pitches, idx + 5), 0.5, accent=True), R(0.5), N(pick(clarinet_pitches, idx + 1), 1.5)]
    return [N(pick(clarinet_pitches, idx), 2.0), N(pick(clarinet_pitches, idx - 2), 2.0)]

def violin_items(number):
    if number <= 4:
        return [R(4.0)]
    idx = number - 5
    if number <= 8:
        return [R(0.5), N(pick(violin_pitches, idx), 1.0), N(pick(violin_pitches, idx + 1), 0.5, accent=True), N(pick(violin_pitches, idx + 3), 1.0), N(pick(violin_pitches, idx + 2), 1.0)]
    if number <= 16:
        return [N(pick(violin_pitches, idx), 1.5), N(pick(violin_pitches, idx + 2), 0.5, accent=True), N(pick(violin_pitches, idx + 3), 1.0), N(pick(violin_pitches, idx + 5), 1.0)]
    if number <= 24:
        return [N(pick(violin_pitches, idx + j), 0.5, accent=(j in [0, 5]), staccato=(j in [2, 6])) for j in range(8)]
    return [N(pick(violin_pitches, idx), 2.0), R(0.5), N(pick(violin_pitches, idx - 2), 1.5)]

def flute_items(number):
    idx = number - 1
    if number <= 8:
        if number % 2 == 1:
            return [R(0.5), N(pick(flute_pitches, idx), 0.5, staccato=True), R(1.0), N(pick(flute_pitches, idx + 2), 1.0), R(1.0)]
        return [R(1.0), N(pick(flute_pitches, idx), 0.5, staccato=True), N(pick(flute_pitches, idx + 1), 0.5), R(0.5), N(pick(flute_pitches, idx + 3), 0.5, staccato=True), R(1.0)]
    if number <= 16:
        items = []
        for j in range(8):
            if j in [2, 5]:
                items.append(R(0.5))
            else:
                items.append(N(pick(flute_pitches, idx + j), 0.5, accent=(j == 0), staccato=True))
        return items
    if number <= 24:
        items = []
        for j in range(16):
            bit = binary_signal[(idx + j) % len(binary_signal)]
            pitch_shift = j if bit else -j
            items.append(N(pick(flute_pitches, idx + pitch_shift), 0.25, accent=(j in [0, 8]), staccato=bool(bit)))
        return items
    if number == 30:
        return [N('E5', 2.0), N('C5', 2.0)]
    return [R(0.5), N(pick(flute_pitches, idx), 1.5), N(pick(flute_pitches, idx - 3), 1.0), R(1.0)]

