def append_sequence(m, seq):
    for pitch_material, dur in seq:
        if pitch_material is None:
            el = note.Rest(quarterLength=dur)
        elif isinstance(pitch_material, (list, tuple)):
            el = chord.Chord(list(pitch_material), quarterLength=dur)
