def tr(pitch_name, semitones):
    return m21.pitch.Pitch(pitch_name).transpose(semitones).nameWithOctave

def ev(pitches, ql):
    if pitches is None:
        obj = m21.note.Rest()
    elif isinstance(pitches, (list, tuple)):
        obj = m21.chord.Chord(list(pitches))
    else:
        obj = m21.note.Note(pitches)
    obj.duration = m21.duration.Duration(ql)
    return obj

def make_measure(number, specs, top=False):
    meas = m21.stream.Measure(number=number)
    if number == 1:
        meas.insert(0, m21.meter.TimeSignature('4/4'))
        meas.insert(0, m21.key.KeySignature(2))
    tempo_marks = {1: ('Andante luminoso', 72), 9: ('Con moto, searching', 84), 17: ('Aperture', 96), 25: ('Tempo I, remembered', 72), 31: ('Molto rit.', 56)}
    dyns = {1: 'mp', 9: 'mf', 17: 'f', 25: 'mp', 31: 'pp'}
    words = {1: 'breath and recursion', 9: 'questions multiplying', 17: 'the lantern opens', 25: 'return as afterimage', 31: 'almost without weight'}
    if number in tempo_marks:
        text, bpm = tempo_marks[number]
        meas.insert(0, m21.tempo.MetronomeMark(text=text, number=bpm))
    if number in dyns:
        meas.insert(0, m21.dynamics.Dynamic(dyns[number]))
    if top and number in words:
        tx = m21.expressions.TextExpression(words[number])
        tx.placement = 'above'
        meas.insert(0, tx)
    for pitches, ql in specs:
        meas.append(ev(pitches, ql))
    return meas

