def flute_specs(number, h):
    c = h['colors']
    k = number - 1
    if number == 32:
        return [('D6', 4)]
    if number <= 8:
        steps = [0, 1, 2, 4, 3]
        durs = [1, 0.5, 0.5, 1, 1]
        return [(c[(k + steps[i]) % len(c)], durs[i]) for i in range(len(steps))]
    if number <= 16:
        steps = [0, 2, 1, 4, 3, 5, 4, 2]
        return [(c[(k + s) % len(c)], 0.5) for s in steps]
    if number <= 24:
        hi = [tr(x, 12) if i in (2, 4) else x for i, x in enumerate(c)]
        steps = [0, 1, 3, 2, 5, 4]
        durs = [0.75, 0.25, 0.5, 0.5, 1, 1]
        return [(hi[(k + steps[i]) % len(hi)], durs[i]) for i in range(len(steps))]
    if number <= 30:
        steps = [0, 2, 1, 4]
        durs = [1.5, 0.5, 1, 1]
        return [(c[(k + steps[i]) % len(c)], durs[i]) for i in range(len(steps))]
    return [(None, 1), ('A5', 1), ('E6', 1), ('C#6', 1)]

def clarinet_specs(number, h):
    c = [tr(x, -12) for x in h['colors']]
    k = number * 2
    if number == 32:
        return [('D4', 4)]
    if number <= 8:
        return [(None, 1), (c[(k + 2) % len(c)], 1), (c[(k + 1) % len(c)], 1), (c[(k + 3) % len(c)], 1)]
    if number <= 16:
        steps = [0, 3, 2, 4, 1]
        durs = [1, 0.5, 0.5, 1, 1]
        return [(c[(k + steps[i]) % len(c)], durs[i]) for i in range(len(steps))]
    if number <= 24:
        steps = [0, 1, 3, 5, 4, 2, 3, 1]
        return [(c[(k + s) % len(c)], 0.5) for s in steps]
    if number <= 30:
        return [(c[k % len(c)], 2), (c[(k + 2) % len(c)], 1), (None, 1)]
    return [('E4', 2), ('C#4', 2)]

def violin_specs(number, h):
    c = h['colors']
    k = number + 1
    if number == 32:
        return [('A5', 1), ('F#5', 1), ('E5', 1), ('D5', 1)]
    if number <= 8:
        steps = [2, 4, 5, 4, 2, 1, 3, 4]
        return [(c[(k + s) % len(c)], 0.5) for s in steps]
    if number <= 16:
        steps = [0, 3, 5, 4, 2, 5, 6, 4]
        return [(c[(k + s) % len(c)], 0.5) for s in steps]
    if number <= 24:
        high = [tr(x, 12) for x in c]
        steps = [0, 2, 4, 6, 5, 3, 4, 2]
        return [(high[(k + s) % len(high)], 0.5) for s in steps]
    if number <= 30:
        steps = [2, 4, 3, 1, 0, 2, 4, 5]
        return [(c[(k + s) % len(c)], 0.5) for s in steps]
    return [('F#5', 2), ('E5', 1), ('C#5', 1)]

def cello_specs(number, h):
    b = h['bass']
    r = h['root']
    if number == 32:
        return [('D2', 4)]
    if number <= 8:
        return [(r, 2), (b[1], 1), (b[2], 1)]
    if number <= 16:
        return [(r, 1), (b[1], 1), (b[2], 1), (b[3], 1)]
    if number <= 24:
        pattern = [r, b[1], b[2], b[1], r, b[3], b[2], b[1]]
        return [(p, 0.5) for p in pattern]
    if number <= 30:
        return [(r, 3), (b[1], 1)]
    return [('A1', 2), ('E2', 1), ('C#2', 1)]

def piano_specs(number, h):
    ch = h['chord']
    r = h['root']
    b = h['bass']
    c = h['colors']
    if number == 32:
        return [(['D2', 'A2', 'D3', 'F#3', 'E4', 'A4', 'D5'], 4)]
    if number <= 8:
        pattern = [[r, ch[2]], [b[1], ch[3]], [ch[0], ch[4]], [b[2], ch[1]], [r, ch[3]], [b[1], ch[4]], [ch[0], ch[2]], [b[2], ch[3]]]
        return [(p, 0.5) for p in pattern]
    if number <= 16:
        return [([r, ch[1], ch[3], ch[4]], 1), ([b[1], ch[0], ch[2]], 1), ([b[2], ch[2], ch[4]], 1), ([b[3], ch[1], ch[3]], 1)]
    if number <= 24:
        return [([r, b[1], ch[2], ch[3], tr(c[0], 12)], 1), ([b[2], ch[1], ch[4], tr(c[2], 12)], 1), ([r, ch[0], ch[3], tr(c[4], 12)], 1), ([b[3], ch[2], ch[4], tr(c[5], 12)], 1)]
    if number <= 30:
        return [([r, ch[0], ch[2], ch[4]], 2), ([b[1], ch[1], ch[3]], 1), ([b[2], ch[2], ch[4]], 1)]
    return [(['A1', 'E2', 'G3', 'D4', 'F#4'], 2), (['A1', 'C#3', 'E4', 'A4'], 2)]

