def rotate(seq, steps):
    steps = steps % len(seq)
    return seq[steps:] + seq[:steps]


def p_from_midi(midi_number):
    p = pitch.Pitch()
    p.midi = int(midi_number)
    return p


def make_note(midi_number, ql, accent=False, staccato=False):
    n = note.Note()
    n.pitch.midi = int(midi_number)
    n.quarterLength = ql
    if accent:
        n.articulations.append(articulations.Accent())
    if staccato:
        n.articulations.append(articulations.Staccato())
    return n


def make_rest(ql):
    r = note.Rest()
    r.quarterLength = ql
    return r


def make_chord(midi_numbers, ql):
    c = chord.Chord([p_from_midi(m) for m in midi_numbers])
    c.quarterLength = ql
    return c


def new_measure(number, clef_name='treble', dyn=None):
    m = stream.Measure(number=number)
    if number == 1:
        if clef_name == 'bass':
            m.insert(0, clef.BassClef())
        else:
            m.insert(0, clef.TrebleClef())
        m.insert(0, meter.TimeSignature('4/4'))
        m.insert(0, key.KeySignature(1))
    if dyn is not None:
        m.insert(0, dynamics.Dynamic(dyn))
    return m


def add_sequence(measure, base_midi, offsets, rhythms, accent_every=None, staccato=False):
    for idx, (offset, ql) in enumerate(zip(offsets, rhythms)):
        if offset is None:
            measure.append(make_rest(ql))
        else:
            accent = accent_every is not None and idx % accent_every == 0
            measure.append(make_note(base_midi + offset, ql, accent=accent, staccato=staccato))


