        color = root + (3 if i % 2 else 5)
        for midi_number, ql in zip([root, root + 7, color], [2.0, 1.0, 1.0]):
            m.append(make_note(midi_number, ql, accent=(ql == 2.0)))
    elif i <= 16:
        for off in rotate([0, 7, 5, 3], i - 9):
            m.append(make_note(root + off, 1.0, staccato=(i % 2 == 0)))
    else:
        m.append(make_note(root, 3.0))
        m.append(make_note(root + 7, 1.0))
    cello_part.append(m)


