import music21
from music21 import stream, note, chord, meter, key, tempo, instrument, dynamics, articulations, expressions, metadata

score = stream.Score(id='GradientMirror')
score.metadata = metadata.Metadata()
score.metadata.title = 'Gradient Mirror'
score.metadata.composer = 'ChatGPT'

TOTAL_MEASURES = 64
BINARY_MOTIF = [0, 7, 2, 9, 4, 11, 5, 12]
LYRIC_MOTIF = [0, 2, 3, 7, 5, 4, 9, 7, 12, 11, 14, 12]
BASS_PROGRESSION = [0, -5, -2, -7, -9, -4, -5, 0]

SECTIONS = [
    {'start': 1, 'end': 16, 'tonic': 'D', 'mode': 'minor', 'bass': 38, 'mid': 62, 'tempo': 92, 'text': 'initialize: pulse and breath'},
    {'start': 17, 'end': 32, 'tonic': 'F', 'mode': 'major', 'bass': 41, 'mid': 65, 'tempo': 96, 'text': 'learning to sing'},
    {'start': 33, 'end': 48, 'tonic': 'A', 'mode': 'minor', 'bass': 45, 'mid': 69, 'tempo': 104, 'text': 'bright recursion'},
    {'start': 49, 'end': 64, 'tonic': 'D', 'mode': 'minor', 'bass': 38, 'mid': 62, 'tempo': 88, 'text': 'memory becomes lullaby'},
]

ROLE_DYNAMICS = {
    'Flute': ['mp', 'mf', 'f', 'mp'],
    'Clarinet': ['p', 'mp', 'mf', 'p'],
    'Violin': ['mp', 'mf', 'f', 'mf'],
    'Violoncello': ['mp', 'mp', 'mf', 'p'],
    'Piano': ['p', 'mp', 'f', 'mp'],
}


def sec_index(measure_no):
    for i, sec in enumerate(SECTIONS):
        if sec['start'] <= measure_no <= sec['end']:
            return i
    return len(SECTIONS) - 1


def section_info(measure_no):
    return SECTIONS[sec_index(measure_no)]


def fit_midi(value, low, high):
    value = int(round(value))
    while value < low:
        value += 12
    while value > high:
        value -= 12
    return value


def make_note(midi, ql, art=None):
    n = note.Note()
    n.pitch.midi = int(midi)
    n.quarterLength = ql
    if art == 'staccato':
        n.articulations.append(articulations.Staccato())
    elif art == 'tenuto':
        n.articulations.append(articulations.Tenuto())
    elif art == 'accent':
        n.articulations.append(articulations.Accent())
    return n


def make_rest(ql):
    return note.Rest(quarterLength=ql)


def midi_pitch(midi):
    p = music21.pitch.Pitch()
    p.midi = int(midi)
    return p


def make_chord(midis, ql, art=None):
    c = chord.Chord([midi_pitch(m) for m in midis])
    c.quarterLength = ql
    if art == 'accent':
        c.articulations.append(articulations.Accent())
    elif art == 'tenuto':
        c.articulations.append(articulations.Tenuto())
    return c


def harmonic_template(measure_no):
    idx = sec_index(measure_no)
    if idx == 1:
        templates = [[0, 4, 7, 9, 14], [0, 2, 7, 11, 16], [0, 4, 7, 12, 14], [0, 5, 9, 11, 16]]
    elif idx == 2:
        templates = [[0, 3, 7, 10, 14], [0, 5, 10, 13, 17], [0, 2, 8, 11, 15], [0, 3, 9, 12, 19]]
    else:
        templates = [[0, 3, 7, 10, 14], [0, 2, 7, 11, 16], [0, 5, 10, 14, 17], [0, 3, 8, 12, 15]]
    return templates[(measure_no - 1) % len(templates)]


def root_for_measure(measure_no, register='bass'):
    sec = section_info(measure_no)
    raw = sec['bass' if register == 'bass' else 'mid'] + BASS_PROGRESSION[(measure_no - sec['start']) % len(BASS_PROGRESSION)]
    if register == 'bass':
        return fit_midi(raw, 36, 52)
    return fit_midi(raw, 52, 70)


def add_global_marks(meas, measure_no, role):
    if measure_no == 1:
        meas.insert(0, meter.TimeSignature('4/4'))
    if measure_no in [1, 17, 33, 49]:
        sec = section_info(measure_no)
        meas.insert(0, key.Key(sec['tonic'], sec['mode']))
        meas.insert(0, tempo.MetronomeMark(number=sec['tempo']))
        meas.insert(0, dynamics.Dynamic(ROLE_DYNAMICS[role][sec_index(measure_no)]))
        if role == 'Flute':
            meas.insert(0, expressions.TextExpression(sec['text']))


def build_flute(meas, measure_no):
    sec = section_info(measure_no)
    local = measure_no - sec['start']
    tonic = sec['mid'] + 12
    idx = sec_index(measure_no)
    if measure_no == TOTAL_MEASURES:
        meas.append(make_note(fit_midi(tonic + 12, 72, 96), 4, 'tenuto'))
        return
    if measure_no % 16 == 0:
        for interval, ql in [(12, 1.0), (14, 1.0), (7, 2.0)]:
            meas.append(make_note(fit_midi(tonic + interval, 72, 96), ql, 'tenuto'))
        return
    if idx == 0:
        for k in range(8):
            if (measure_no + k) % 7 == 0:
                meas.append(make_rest(0.5))
            else:
                interval = BINARY_MOTIF[(local + k) % len(BINARY_MOTIF)] + (12 if k > 5 else 0)
                meas.append(make_note(fit_midi(tonic + interval, 72, 94), 0.5, 'staccato' if k % 2 else None))
    elif idx == 1:
        durations = [1.0, 0.5, 0.5, 1.0, 0.5, 0.5]
        steps = [0, 2, 3, 5, 4, 7]
        for k, ql in enumerate(durations):
            interval = LYRIC_MOTIF[(local + steps[k]) % len(LYRIC_MOTIF)]
            meas.append(make_note(fit_midi(tonic + interval, 72, 94), ql, 'tenuto' if ql >= 1 else None))
    elif idx == 2:
        for k in range(16):
            if k in [3, 11] and measure_no % 3 == 0:
                meas.append(make_rest(0.25))
            else:
                interval = BINARY_MOTIF[(local * 3 + k * 2) % len(BINARY_MOTIF)] + (12 if k % 5 == 0 else 0)
                meas.append(make_note(fit_midi(tonic + interval, 74, 96), 0.25, 'accent' if k % 4 == 0 else 'staccato'))
    else:
        durations = [1.5, 0.5, 0.5, 0.5, 1.0]
        steps = [12, 11, 7, 5, 0]
        for k, ql in enumerate(durations):
            interval = steps[(k + local) % len(steps)]
            meas.append(make_note(fit_midi(tonic + interval, 72, 94), ql, 'tenuto' if ql >= 1 else None))


def build_clarinet(meas, measure_no):
    sec = section_info(measure_no)
    local = measure_no - sec['start']
    tonic = sec['mid']
    idx = sec_index(measure_no)
    if measure_no == TOTAL_MEASURES:
        meas.append(make_note(fit_midi(tonic + 7, 50, 78), 4, 'tenuto'))
        return
    if measure_no % 8 == 0:
        meas.append(make_note(fit_midi(tonic + LYRIC_MOTIF[local % len(LYRIC_MOTIF)], 50, 78), 2, 'tenuto'))
        meas.append(make_note(fit_midi(tonic + 7, 50, 78), 2, 'tenuto'))
        return
    if idx == 2:
        for k in range(8):
            interval = BINARY_MOTIF[(local + 7 - k) % len(BINARY_MOTIF)]
            meas.append(make_note(fit_midi(tonic + interval - 5, 50, 78), 0.5, 'staccato' if k % 2 else None))
    else:
        durations = [1.0, 0.5, 0.5, 1.0, 1.0]
        contour = [7, 5, 3, 2, 0]
        for k, ql in enumerate(durations):
            interval = contour[(k + local) % len(contour)] + (2 if idx == 1 and k == 3 else 0)
            meas.append(make_note(fit_midi(tonic + interval, 50, 78), ql, 'tenuto' if ql == 1.0 else None))


def build_violin(meas, measure_no):
    sec = section_info(measure_no)
    local = measure_no - sec['start']
    tonic = sec['mid'] + 7
    idx = sec_index(measure_no)
    if measure_no == TOTAL_MEASURES:
        meas.append(make_note(fit_midi(tonic + 5, 55, 88), 4, 'tenuto'))
        return
    if measure_no % 16 == 0:
        meas.append(make_note(fit_midi(tonic + 12, 55, 88), 3, 'tenuto'))
        meas.append(make_note(fit_midi(tonic + 7, 55, 88), 1, 'tenuto'))
        return
    if idx == 0:
        durations = [2.0, 1.0, 1.0]
        for k, ql in enumerate(durations):
            interval = LYRIC_MOTIF[(local + k * 2) % len(LYRIC_MOTIF)]
            meas.append(make_note(fit_midi(tonic + interval, 55, 88), ql, 'tenuto'))
    elif idx == 1:
        durations = [1.5, 0.5, 1.0, 1.0]
        for k, ql in enumerate(durations):
            interval = LYRIC_MOTIF[(local + k + 3) % len(LYRIC_MOTIF)]
            meas.append(make_note(fit_midi(tonic + interval, 55, 88), ql, 'tenuto' if ql >= 1 else None))
    elif idx == 2:
        for k in range(8):
            interval = LYRIC_MOTIF[(local * 2 + k) % len(LYRIC_MOTIF)]
            meas.append(make_note(fit_midi(tonic + interval, 57, 90), 0.5, 'accent' if k in [0, 4] else None))
    else:
        durations = [1.0, 1.0, 2.0]
        intervals = [12, 9, 7, 5, 3, 2, 0]
        for k, ql in enumerate(durations):
            interval = intervals[(local + k) % len(intervals)]
            meas.append(make_note(fit_midi(tonic + interval, 55, 88), ql, 'tenuto'))


def build_cello(meas, measure_no):
    root = root_for_measure(measure_no, 'bass')
    sec = section_info(measure_no)
    idx = sec_index(measure_no)
    if measure_no == TOTAL_MEASURES:
        meas.append(make_note(38, 4, 'tenuto'))
        return
    if measure_no % 8 == 0:
        meas.append(make_note(root, 3, 'tenuto'))
        meas.append(make_note(fit_midi(root + 7, 36, 60), 1, 'tenuto'))
        return
    if idx == 2:
        pattern = [0, 7, 10, 12]
        for k in range(4):
            meas.append(make_note(fit_midi(root + pattern[(k + measure_no) % 4], 36, 60), 1, 'accent' if k == 0 else 'tenuto'))
    else:
        pattern = [0, 7, 12, 10 if sec['mode'] == 'minor' else 9]
        durations = [1.5, 0.5, 1.0, 1.0]
        for k, ql in enumerate(durations):
            meas.append(make_note(fit_midi(root + pattern[k], 36, 60), ql, 'tenuto'))


def piano_voicing(measure_no, root, bright=False):
    template = harmonic_template(measure_no)
    bass = fit_midi(root - 12, 36, 52)
    upper_root = fit_midi(root + 12, 55, 67)
    mids = [fit_midi(upper_root + i, 55, 84 if bright else 79) for i in template]
    return [bass] + mids


def build_piano(meas, measure_no):
    root = root_for_measure(measure_no, 'mid')
    idx = sec_index(measure_no)
    if measure_no == TOTAL_MEASURES:
        meas.append(make_chord([38, 50, 57, 62, 65, 69, 74], 4, 'tenuto'))
        return
    if idx == 0:
        meas.append(make_chord(piano_voicing(measure_no, root), 1.5))
        meas.append(make_note(fit_midi(root + BINARY_MOTIF[measure_no % 8] + 24, 72, 88), 0.5, 'staccato'))
        meas.append(make_note(fit_midi(root + BINARY_MOTIF[(measure_no + 3) % 8] + 24, 72, 88), 0.5, 'staccato'))
        meas.append(make_chord(piano_voicing(measure_no, root + 5), 1.5))
    elif idx == 1:
        meas.append(make_chord(piano_voicing(measure_no, root), 1.0))
        meas.append(make_note(fit_midi(root + 19, 60, 84), 0.5))
        meas.append(make_note(fit_midi(root + 14, 60, 84), 0.5))
        meas.append(make_chord(piano_voicing(measure_no, root + 7), 1.0))
        meas.append(make_chord(piano_voicing(measure_no, root + 2, bright=True), 1.0))
    elif idx == 2:
        for k in range(8):
            local_root = root + BASS_PROGRESSION[k % len(BASS_PROGRESSION)]
            meas.append(make_chord(piano_voicing(measure_no + k, local_root, bright=True), 0.5, 'accent' if k in [0, 4] else None))
    else:
        meas.append(make_chord(piano_voicing(measure_no, root), 2.0, 'tenuto'))
        meas.append(make_note(fit_midi(root + 24, 72, 86), 1.0, 'tenuto'))
        meas.append(make_chord(piano_voicing(measure_no, root - 5), 1.0))


def make_part(role, inst, builder):
    part = stream.Part(id=role)
    part.partName = role
    part.insert(0, inst)
    for measure_no in range(1, TOTAL_MEASURES + 1):
        meas = stream.Measure(number=measure_no)
        add_global_marks(meas, measure_no, role)
        builder(meas, measure_no)
        part.append(meas)
    return part

