def make_note(pitch_name, ql, art=None):
    if pitch_name is None:
        obj = note.Rest()
    else:
        obj = note.Note(pitch_name)
        if art == 'staccato':
            obj.articulations.append(articulations.Staccato())
        elif art == 'tenuto':
            obj.articulations.append(articulations.Tenuto())
    obj.duration.quarterLength = ql
    return obj

def make_chord(pitches, ql, art=None):
    obj = chord.Chord(pitches)
    obj.duration.quarterLength = ql
    if art == 'staccato':
        obj.articulations.append(articulations.Staccato())
    elif art == 'tenuto':
        obj.articulations.append(articulations.Tenuto())
    return obj

def make_measure(number, items, dyn=None, text=None):
    m = stream.Measure(number=number)
    if number == 1:
        m.insert(0, meter.TimeSignature('4/4'))
        m.insert(0, key.KeySignature(2))
    if dyn is not None:
        m.insert(0, dynamics.Dynamic(dyn))
    if text is not None:
        tx = expressions.TextExpression(text)
        tx.placement = 'above'
        m.insert(0, tx)
    for item in items:
        m.append(item)
    return m

