        return [make_note('D4', 4, 'tenuto')]
    idx = (i - 33)
    return [make_note(clarinet_melody[idx % len(clarinet_melody)], 2), make_note(clarinet_melody[(idx + 1) % len(clarinet_melody)], 1), make_note(None, 1)]

def violin_contents(i):
    if i <= 8:
        return [make_note(violin_melody[(i - 1) % len(violin_melody)], 2, 'tenuto'), make_note(None, 0.5), make_note(violin_melody[i % len(violin_melody)], 1.5)]
    if i <= 16:
        idx = (i - 9) * 4
        return [make_note(violin_melody[(idx + j) % len(violin_melody)], 0.5, 'staccato' if j in [1, 5] else None) for j in range(8)]
    if i <= 24:
        idx = (i - 17) * 2
        return [make_note(violin_melody[idx % len(violin_melody)], 1.5), make_note(violin_melody[(idx + 1) % len(violin_melody)], 0.5), make_note(violin_melody[(idx + 2) % len(violin_melody)], 1), make_note(violin_melody[(idx + 3) % len(violin_melody)], 1)]
    if i <= 32:
        idx = (i - 25) * 3
        return [make_note(violin_melody[(idx + j) % len(violin_melody)], 1) for j in range(4)]
    if i == 40:
        return [make_note('A4', 2), make_note('D5', 2, 'tenuto')]
    idx = (i - 33) * 2
    return [make_note(violin_melody[idx % len(violin_melody)], 2), make_note(None, 0.5), make_note(violin_melody[(idx + 1) % len(violin_melody)], 1.5)]

def cello_contents(i):
    root, fifth, octave = bass_shapes[(i - 1) % len(bass_shapes)]
    if i <= 16:
        return [make_note(root, 4, 'tenuto')]
    if i <= 24:
        return [make_note(root, 2, 'tenuto'), make_note(fifth, 2)]
    if i <= 32:
        return [make_note(root, 1), make_note(fifth, 1), make_note(octave, 1), make_note(fifth, 1)]
    if i == 40:
        return [make_note('D2', 4, 'tenuto')]
    return [make_note(root, 3, 'tenuto'), make_note(None, 1)]

def piano_contents(i):
    ch = piano_progression[(i - 1) % len(piano_progression)]
    if i == 40:
