def section_dynamic(measure_number, mapping):
    if measure_number == 1:
        return mapping[0]
    if measure_number == 9:
        return mapping[1]
    if measure_number == 17:
        return mapping[2]
    if measure_number == 21:
        return mapping[3]
    return None


def build_violin_measure(measure_number, events, final=False):
    m = stream.Measure(number=measure_number)
    if measure_number == 1:
        m.append(meter.TimeSignature('4/4'))
    dyn = section_dynamic(measure_number, ['mp', 'mf', 'pp', 'f'])
    if dyn:
        m.append(dynamics.Dynamic(dyn))
    for pitch_name, dur in events:
        if pitch_name is None:
            elem = note.Rest(quarterLength=dur)
        else:
            elem = note.Note(pitch_name, quarterLength=dur)
        m.append(elem)
    if final:
        m.rightBarline = 'final'
    return m


def build_cello_measure(measure_number, events, final=False):
    m = stream.Measure(number=measure_number)
    if measure_number == 1:
        m.append(meter.TimeSignature('4/4'))
    dyn = section_dynamic(measure_number, ['p', 'mp', 'pp', 'mf'])
    if dyn:
        m.append(dynamics.Dynamic(dyn))
    for pitch_name, dur in events:
        m.append(note.Note(pitch_name, quarterLength=dur))
    if final:
        m.rightBarline = 'final'
    return m


def add_pair(m, pitches, a, b, dur=0.5):
    m.append(chord.Chord([pitches[a], pitches[b]], quarterLength=dur))


def build_piano_measure(measure_number, pitches, style, final=False):
    m = stream.Measure(number=measure_number)
    if measure_number == 1:
        m.append(meter.TimeSignature('4/4'))
    dyn = section_dynamic(measure_number, ['p', 'mf', 'pp', 'f'])
    if dyn:
        m.append(dynamics.Dynamic(dyn))

    if style == 'flow':
        for a, b in [(0, 2), (1, 3), (0, 3), (1, 2), (0, 2), (1, 3), (2, 3), (0, 1)]:
            add_pair(m, pitches, a, b)
    elif style == 'shadow':
        for a, b in [(0, 1), (2, 3), (1, 2), (0, 3), (1, 3), (0, 2), (2, 3), (0, 1)]:
            add_pair(m, pitches, a, b)
    elif style == 'spacious':
        m.append(chord.Chord([pitches[0], pitches[2]], quarterLength=2))
        m.append(note.Rest(quarterLength=1))
        m.append(chord.Chord([pitches[1], pitches[3]], quarterLength=1))
    elif style == 'return':
        for a, b in [(0, 2), (1, 3), (0, 3), (1, 2), (0, 2), (1, 3), (0, 1), (2, 3)]:
            add_pair(m, pitches, a, b)

    if final:
        m.rightBarline = 'final'
    return m


