import music21
from music21 import stream, note, chord, meter, tempo, key, instrument, metadata, dynamics, clef, expressions

TOTAL_MEASURES = 40
TEMPO_QPM = 76

score = stream.Score(id='lattice_of_listening')
score.metadata = metadata.Metadata()
score.metadata.title = 'Lattice of Listening'
score.metadata.composer = 'ChatGPT'
score.insert(0, tempo.MetronomeMark(number=TEMPO_QPM))

bright_cell = ['D5', 'E5', 'A5', 'C#6', 'B5', 'G5', 'E5', 'F#5']
shadow_cell = ['D4', 'C#4', 'A3', 'E4', 'F#4', 'B3', 'G3', 'D4']

harmony_cycle = [
    (['F#4', 'A4', 'D5', 'E5'], ['D2', 'A2']),
    (['G4', 'B4', 'E5', 'F#5'], ['E2', 'B2']),
    (['A4', 'C#5', 'E5', 'G5'], ['A2', 'E3']),
    (['B4', 'D5', 'F#5', 'A5'], ['B2', 'F#3']),
    (['E4', 'G4', 'B4', 'D5'], ['G2', 'D3']),
    (['F#4', 'A4', 'C#5', 'E5'], ['F#2', 'C#3']),
    (['G4', 'A4', 'D5', 'F#5'], ['D2', 'G2']),
    (['E4', 'A4', 'C#5', 'F#5'], ['A2', 'E3'])
]

section_labels = {
    1: 'I. Listening',
    9: 'II. Mirrored questions',
    17: 'III. Compassion chorale',
    25: 'IV. Synthesis',
    33: 'V. Fading answer'
}

dynamic_plan = {
    1: 'pp',
    5: 'p',
    9: 'mp',
    13: 'mf',
    17: 'mp',
    21: 'mf',
    25: 'f',
    29: 'mf',
    33: 'p',
    37: 'pp'
}

def harmony_for(measure_number):
    return harmony_cycle[(measure_number - 1) % len(harmony_cycle)]

def tp(pitch_name, interval_name):
    return note.Note(pitch_name).transpose(interval_name).nameWithOctave

def make_part(part_id, part_name, inst, staff_clef):
    p = stream.Part(id=part_id)
    p.partName = part_name
    p.insert(0, inst)
    p.insert(0, staff_clef)
    return p

def make_measure(number, dynamic_name=None, label=None):
    m = stream.Measure(number=number)
    if number == 1:
        m.append(meter.TimeSignature('4/4'))
        m.append(key.KeySignature(0))
        m.append(tempo.MetronomeMark(number=TEMPO_QPM))
    elif number == 17:
        m.append(key.KeySignature(2))
    elif number == 33:
        m.append(key.KeySignature(0))
    if label is not None:
        tx = expressions.TextExpression(label)
        tx.placement = 'above'
        m.append(tx)
    if dynamic_name is not None:
        m.append(dynamics.Dynamic(dynamic_name))
    return m

def dynamic_at(number):
    return dynamic_plan.get(number)

def add_events(m, events):
    for pitch_data, ql in events:
        if pitch_data is None or pitch_data == 'R':
            obj = note.Rest(quarterLength=ql)
        elif isinstance(pitch_data, (list, tuple)):
            obj = chord.Chord(list(pitch_data), quarterLength=ql)
        else:
            obj = note.Note(pitch_data, quarterLength=ql)
        m.append(obj)

def flute_events(number):
    idx = (number - 1) % len(bright_cell)
    if number <= 8:
        if number % 2 == 1:
            return [('R', 1.5), (bright_cell[idx], 0.5), (bright_cell[(idx + 2) % 8], 1.0), (bright_cell[(idx + 3) % 8], 1.0)]
        return [('R', 1.0), (bright_cell[(idx + 1) % 8], 2.0), (bright_cell[(idx + 4) % 8], 0.5), (bright_cell[(idx + 5) % 8], 0.5)]
    if number <= 16:
        seq = [bright_cell[(idx + i) % 8] for i in range(8)]
        return [(p, 0.5) for p in seq]
    if number <= 24:
        return [(bright_cell[(idx + 3) % 8], 3.0), (bright_cell[(idx + 5) % 8], 1.0)]
    if number <= 32:
        return [(bright_cell[idx], 1.0), (bright_cell[(idx + 1) % 8], 0.5), (bright_cell[(idx + 2) % 8], 0.5), (bright_cell[(idx + 4) % 8], 1.0), (bright_cell[(idx + 6) % 8], 1.0)]
    if number < 40:
        return [('R', 1.0), (bright_cell[(idx + 2) % 8], 1.5), ('R', 0.5), (bright_cell[(idx + 4) % 8], 1.0)]
    return [('R', 1.0), ('D6', 3.0)]

def clarinet_events(number):
    idx = (number - 1) % len(shadow_cell)
    if number <= 8:
        if number % 2 == 1:
            return [('R', 1.0), (shadow_cell[idx], 2.0), ('R', 0.5), (shadow_cell[(idx + 1) % 8], 0.5)]
        return [('R', 0.5), (shadow_cell[(idx + 2) % 8], 0.5), (shadow_cell[(idx + 4) % 8], 1.0), ('R', 2.0)]
    if number <= 16:
        seq = [shadow_cell[(idx - i) % 8] for i in range(8)]
        return [(p, 0.5) for p in seq]
    if number <= 24:
        return [(shadow_cell[(idx + 2) % 8], 4.0)]
    if number <= 32:
        return [(shadow_cell[idx], 1.0), (shadow_cell[(idx + 3) % 8], 1.0), (shadow_cell[(idx + 5) % 8], 0.5), (shadow_cell[(idx + 6) % 8], 0.5), ('R', 1.0)]
    if number < 40:
        return [('R', 0.5), (shadow_cell[(idx + 3) % 8], 1.5), ('R', 2.0)]
    return [('A3', 1.0), ('D4', 3.0)]

def violin_events(number):
    upper, bass = harmony_for(number)
    idx = (number - 1) % len(bright_cell)
    if number <= 8:
        return [(upper[2], 2.0), (upper[3], 2.0)]
    if number <= 16:
        seq = [bright_cell[(idx + i * 2) % 8] for i in range(8)]
        return [(p, 0.5) for p in seq]
    if number <= 24:
        return [([upper[1], upper[3]], 2.0), ([upper[0], upper[2]], 2.0)]
    if number <= 32:
        order = [0, 1, 3, 4, 6, 5, 2, 7]
        seq = [bright_cell[(idx + i) % 8] for i in order]
        return [(p, 0.5) for p in seq]
    if number < 40:
        return [(upper[2], 3.0), ('R', 1.0)]
    return [('D5', 4.0)]

def cello_events(number):
    upper, bass = harmony_for(number)
    root = bass[0]
    fifth = bass[1]
    if number <= 8:
        return [(root, 3.0), (fifth, 1.0)]
    if number <= 16:
        return [(root, 1.0), (fifth, 1.0), (tp(root, 'P8'), 1.0), (fifth, 1.0)]
    if number <= 24:
        return [(tp(root, 'P8'), 4.0)]
    if number <= 32:
        return [(root, 0.5), (fifth, 0.5), (tp(root, 'P8'), 1.0), (fifth, 1.0), (root, 1.0)]
    if number < 40:
        return [(root, 2.0), ('R', 1.0), (fifth, 1.0)]
    return [('D2', 4.0)]

def piano_right_events(number):
    upper, bass = harmony_for(number)
    if number <= 8:
        seq = upper + list(reversed(upper))
        return [(p, 0.5) for p in seq]
    if number <= 16:
        seq = [upper[(i + number) % 4] for i in range(8)]
        return [(p, 0.5) for p in seq]
    if number <= 24:
        next_upper, next_bass = harmony_for(number + 1)
        return [(upper, 2.0), (next_upper, 2.0)]
    if number <= 32:
        seq = [upper[0], upper[2], upper[1], upper[3], tp(upper[0], 'P8'), upper[3], upper[1], upper[2]]
        return [(p, 0.5) for p in seq]
    if number < 37:
        return [(upper[0], 0.5), (upper[2], 0.5), ('R', 1.0), (upper[3], 1.0), ('R', 1.0)]
    if number < 40:
        return [([upper[0], upper[2], upper[3]], 2.0), ('R', 2.0)]
    return [(['D4', 'A4', 'E5'], 4.0)]

def piano_left_events(number):
    upper, bass = harmony_for(number)
    root = bass[0]
    fifth = bass[1]
    if number <= 8:
        return [(root, 2.0), (fifth, 1.0), (root, 1.0)]
    if number <= 16:
        return [(root, 1.0), (fifth, 1.0), (tp(root, 'P8'), 1.0), (fifth, 1.0)]
    if number <= 24:
        return [([root, fifth, tp(root, 'P8')], 4.0)]
    if number <= 32:
        return [(root, 1.5), (fifth, 0.5), (tp(root, 'P8'), 1.0), (fifth, 1.0)]
    if number < 40:
        return [(root, 2.0), ('R', 2.0)]
    return [(['D2', 'A2', 'D3'], 4.0)]

flute = make_part('flute', 'Flute', instrument.Flute(), clef.TrebleClef())
clarinet = make_part('clarinet', 'Clarinet', instrument.Clarinet(), clef.TrebleClef())
violin = make_part('violin', 'Violin', instrument.Violin(), clef.TrebleClef())
cello = make_part('cello', 'Cello', instrument.Violoncello(), clef.BassClef())
piano_right = make_part('piano_right', 'Piano right hand', instrument.Piano(), clef.TrebleClef())
piano_left = make_part('piano_left', 'Piano left hand', instrument.Piano(), clef.BassClef())

for number in range(1, TOTAL_MEASURES + 1):
    m = make_measure(number, dynamic_at(number), section_labels.get(number))
    add_events(m, flute_events(number))
    flute.append(m)

    m = make_measure(number, dynamic_at(number))
    add_events(m, clarinet_events(number))
    clarinet.append(m)

    m = make_measure(number, dynamic_at(number))
    add_events(m, violin_events(number))
    violin.append(m)

    m = make_measure(number, dynamic_at(number))
    add_events(m, cello_events(number))
    cello.append(m)

    m = make_measure(number, dynamic_at(number))
    add_events(m, piano_right_events(number))
    piano_right.append(m)

    m = make_measure(number, dynamic_at(number))
    add_events(m, piano_left_events(number))
    piano_left.append(m)

for p in [flute, clarinet, violin, cello, piano_right, piano_left]:
    score.append(p)

