    return note.Note(pitch, quarterLength=ql)


def CH(pitches, ql):
    return chord.Chord(pitches, quarterLength=ql)


def R(ql):
    r = note.Rest()
    r.duration.quarterLength = ql
    return r


def arp(tones):
    order = [0, 1, 2, 3, 2, 1, 2, 3]
    return [N(tones[k], 0.5) for k in order]


