prog = ['D','Bm','G','A','D','Bm','Em','A'] * 3
roots = {'D':'D2','Bm':'B1','G':'G1','A':'A1','Em':'E2'}
flute_tones = {
    'D':['D5','F#5','A5'], 'Bm':['B4','D5','F#5'],
    'G':['G5','B5','D6'], 'A':['A4','C#5','E5'], 'Em':['E5','G5','B5']
}
clarinet_tones = {
