    'G':['G4','B4','D5'], 'A':['A3','C#4','E4'], 'Em':['E4','G4','B4']
}
scale = ['D5','E5','F#5','G5','A5','B5','C#6','D6']

def N(x, q=1.0):
    return note.Note(x, quarterLength=q)

def C(xs, q=1.0):
    return chord.Chord(xs, quarterLength=q)

def R(q=1.0):
    return note.Rest(quarterLength=q)

def add(part, num, events, mark=None):
    m = stream.Measure(number=num)
    if mark is not None:
        m.insert(0, dynamics.Dynamic(mark))
    for e in events:
        m.append(e)
    part.append(m)

for i in range(24):
    num = i + 1
    ch = prog[i]
    section = i // 8
    pos = i % 8
    mark = 'p' if num == 1 else ('mp' if num == 9 else ('mf' if num == 17 else None))

    ft = flute_tones[ch]
    if section == 0:
        idx = [0,1,2,1] if pos % 2 == 0 else [1,2,1,0]
        f_ev = [N(ft[idx[0]],1), N(ft[idx[1]],1), N(ft[idx[2]],1), N(ft[idx[3]],1)]
        if pos == 7:
            f_ev = [N(ft[2],0.5), N(ft[1],0.5), N(ft[0],1), N(ft[2],2)]
    elif section == 1:
        base = (i + pos) % 8
        f_ev = [N(scale[base],0.5), N(scale[(base+2)%8],0.5), N(ft[2],1), N(ft[1],1), N(ft[0],1)]
        if pos in (3,7):
            f_ev = [N(ft[1],0.5), N(ft[2],0.5), N(ft[0],1), N(ft[1],2)]
    else:
        f_ev = [N(ft[0],1), N(ft[2],1), N(ft[1],1), N(ft[2],1)]
        if pos == 7:
            f_ev = [N('D6',1), N('C#6',1), N('B5',1), N('A5',1)]

    ct = clarinet_tones[ch]
    if section == 1 and pos in (2,6):
        cl_ev = [R(0.5), N(ct[2],0.5), N(ct[1],1), N(ct[0],2)]
    elif pos in (3,7):
        cl_ev = [N(ct[2],1), N(ct[1],1), N(ct[0],2)]
    else:
        cl_ev = [N(ct[pos % 3],2), N(ct[(pos+1) % 3],2)]

    root = roots[ch]
    if pos in (3,7):
        vc_ev = [N(root,1), N(root,1), N(root,2)]
    else:
        vc_ev = [N(root,4)]

    pt = piano_tones[ch]
    if pos == 7:
        pf_ev = [C([pt[0], pt[1], pt[2], flute_tones[ch][0]],4)]
    else:
        arp = [0,1,2,1,0,2,1,2] if section == 1 else [0,1,2,1,0,1,2,1]
        pf_ev = [N(pt[j],0.5) for j in arp]

    add(flute, num, f_ev, mark)
    add(clarinet, num, cl_ev, mark)
    add(cello, num, vc_ev, mark)
    add(piano, num, pf_ev, mark)

from music21 import stream, note, chord, tempo, meter, instrument, key

score = stream.Score()

piano = stream.Part()
piano.insert(0, instrument.Piano())
piano.insert(0, tempo.MetronomeMark(number=92))
piano.insert(0, meter.TimeSignature('4/4'))
piano.insert(0, key.Key('D', 'dorian'))

# Section A: Emergence - sparse, contemplative patterns
pattern_a = ['D4', 'F4', 'A4', 'C5', 'A4', 'F4', 'E4', 'D4']
for cycle in range(6):
    for pitch in pattern_a:
        n = note.Note(pitch, quarterLength=0.5)
        piano.append(n)
    if cycle % 2 == 0:
        bass = note.Note('D3', quarterLength=2)
        piano.append(bass)
    else:
        piano.append(note.Rest(quarterLength=2))

# Section B: Layering - adding harmonic depth
for cycle in range(8):
    if cycle % 2 == 0:
        chords_b = [
            chord.Chord(['D3', 'D4', 'F4'], quarterLength=1),
            chord.Chord(['F3', 'A3', 'C4'], quarterLength=1),
            chord.Chord(['G3', 'C4', 'E4'], quarterLength=1),
            chord.Chord(['A3', 'D4', 'F4'], quarterLength=1)
        ]
        for c in chords_b:
            piano.append(c)
    else:
        for i, pitch in enumerate(['A4', 'C5', 'D5', 'E5', 'D5', 'C5', 'A4', 'G4']):
            n = note.Note(pitch, quarterLength=0.5)
            piano.append(n)

# Section C: Presence - fuller texture with continuous motion
for measure in range(12):
    if measure % 3 == 0:
        arp = ['D4', 'E4', 'F4', 'A4', 'C5', 'D5', 'C5', 'A4', 'F4', 'E4', 'D4', 'C4']
        for pitch in arp:
            piano.append(note.Note(pitch, quarterLength=1.0/3))
    elif measure % 3 == 1:
        piano.append(chord.Chord(['D3', 'A3', 'D4', 'F4'], quarterLength=2))
        piano.append(chord.Chord(['C3', 'G3', 'C4', 'E4'], quarterLength=2))
    else:
        melody = ['F4', 'E4', 'D4', 'C4']
        for pitch in melody:
            piano.append(note.Note(pitch, quarterLength=1))

# Section D: Dissolution - returning to spaciousness
for cycle in range(6):
    spacing = 0.75 if cycle < 3 else 1.0
    for pitch in pattern_a[:6]:
        n = note.Note(pitch, quarterLength=spacing)
        piano.append(n)
    rest_length = 4 - (6 * spacing)
    if rest_length > 0:
        piano.append(note.Rest(quarterLength=rest_length))

# Resolution
piano.append(chord.Chord(['D3', 'A3', 'D4', 'F4'], quarterLength=6))
piano.append(note.Rest(quarterLength=2))

score.append(piano)

