def scale_pitch(degree, octave):
    return scale[degree % len(scale)] + str(octave + degree // len(scale))


def fold_root(degree):
    return degree if degree <= 4 else degree - 8


def make_part(pid, inst, name):
    part = stream.Part(id=pid)
    part.partName = name
    part.insert(0, inst)
    part.insert(0, meter.TimeSignature('4/4'))
    part.insert(0, tempo.MetronomeMark(number=BPM))
    part.insert(0, key.Key('D', 'minor'))
    return part


def add_dynamic(part, mark):
    part.append(dynamics.Dynamic(mark))


def add_articulation(music_object, art):
    if art == 'staccato':
        music_object.articulations.append(articulations.Staccato())
    elif art == 'tenuto':
        music_object.articulations.append(articulations.Tenuto())
    elif art == 'accent':
        music_object.articulations.append(articulations.Accent())


def add_note(part, pitch_name, ql, art=None):
    n = note.Note(pitch_name)
    n.duration.quarterLength = ql
    if art is not None:
        add_articulation(n, art)
    part.append(n)


def add_chord(part, pitch_names, ql, art=None):
    c = chord.Chord(pitch_names)
    c.duration.quarterLength = ql
    if art is not None:
        add_articulation(c, art)
    part.append(c)


def add_rest(part, ql):
    r = note.Rest()
    r.duration.quarterLength = ql
    part.append(r)


