    ('D', [2, 6, 9]), ('Bm', [11, 2, 6]), ('G', [7, 11, 2]), ('A', [9, 1, 4]),
    ('Em', [4, 7, 11]), ('F#m', [6, 9, 1]), ('G', [7, 11, 2]), ('A', [9, 1, 4])
]
BPROG = [
    ('Em', [4, 7, 11]), ('A', [9, 1, 4]), ('D', [2, 6, 9]), ('G', [7, 11, 2]),
    ('C#dim', [1, 4, 7]), ('F#m', [6, 9, 1]), ('Bm', [11, 2, 6]), ('A', [9, 1, 4])
]
CODA = [
    ('D', [2, 6, 9]), ('G', [7, 11, 2]), ('D', [2, 6, 9]), ('A', [9, 1, 4]),
    ('Bm', [11, 2, 6]), ('G', [7, 11, 2]), ('A', [9, 1, 4]), ('D', [2, 6, 9])
]
MOTIF = [0, 2, 1, 3, 2, 4, 3, 5]

def sec(m):
    if m <= 16:
        return 'A'
    if m <= 32:
        return 'B'
    if m <= 48:
        return 'A2'
    return 'Coda'

def harmony(m):
    s = sec(m)
    if s == 'B':
        return BPROG[(m - 17) % 8]
    if s == 'Coda':
        return CODA[m - 49]
    return PROG[(m - 1) % 8]

def midi(pc, octv):
    return 12 * (octv + 1) + pc

def deg_midi(deg, oct0):
    return midi(DPCS[deg % 7], oct0 + deg // 7)

def fit(mm, lo, hi):
    while mm < lo:
        mm += 12
    while mm > hi:
        mm -= 12
    return mm

def N(mm, ql, vel=70, art=None):
    n = note.Note(pitch.Pitch(int(mm)))
    n.duration.quarterLength = ql
    n.volume.velocity = int(vel)
    if art == 'staccato':
        n.articulations.append(articulations.Staccato())
    elif art == 'accent':
        n.articulations.append(articulations.Accent())
    return n

def R(ql):
    r = note.Rest()
    r.duration.quarterLength = ql
    return r

def C(mids, ql, vel=64):
    uniq = []
    for x in mids:
        xi = int(x)
        if xi not in uniq:
            uniq.append(xi)
    c = chord.Chord([pitch.Pitch(x) for x in uniq])
    c.duration.quarterLength = ql
    c.volume.velocity = int(vel)
    return c

def put(meas, events):
    for ev in events:
        if ev[0] == 'n':
            meas.append(N(*ev[1:]))
        elif ev[0] == 'r':
