def dyn_for(m):
    return {1: 'mp', 9: 'mf', 17: 'f', 25: 'ff', 33: 'mf', 41: 'f', 49: 'mp', 55: 'pp', 56: 'ppp'}.get(m)

def add_dyn(meas, m):
