def melody_midi(m, idx, oct0, lo, hi, shift=0):
    s = sec(m)
    if idx == 0:
        return chord_tone(m, 0, oct0, lo, hi)
    if s == 'B':
        deg = (m - 17) * 2 + MOTIF[(idx + (m % 3)) % 8] + shift
    elif s == 'Coda':
        deg = (m - 49) + MOTIF[idx % 8] + shift
    else:
        deg = (m - 1) + MOTIF[(idx + ((m - 1) % 4)) % 8] + shift
