        return [('n', bass_note(root, 2), 2, 62), ('n', bass_note(fifth, 2), 2, 58)]
    return [('n', bass_note(root, 2), 1, 62), ('n', bass_note(fifth, 2), 1, 58), ('n', bass_note(root, 2), 2, 60)]

def events_pno(m):
    s = sec(m)
    name, pcs = harmony(m)
    pos = (m - 1) % 4
    def pm(pc, octv):
        return fit(midi(pc, octv), 36, 96)
    if s == 'Coda':
        if m < 56:
            c1 = [pm(pcs[0], 2), pm(pcs[1], 3), pm(pcs[2], 3), pm(pcs[0], 4)]
            c2 = [pm(pcs[2], 2), pm(pcs[0], 3), pm(pcs[1], 3), pm(pcs[2], 4)]
            return [('c', c1, 2, 58), ('c', c2, 2, 54)]
        final = [midi(2, 2), midi(9, 2), midi(2, 3), midi(6, 3), midi(9, 3), midi(2, 4)]
        return [('c', final, 4, 46)]
    if s == 'B':
        ev = []
        for beat in range(4):
            if beat in (0, 2):
                mids = [pm(pcs[0], 2), pm(pcs[1], 3), pm(pcs[2], 3), pm(pcs[0], 4)]
                ev.append(('c', mids, 1, 76 if beat == 0 else 70))
            else:
                ev.append(('n', pm(pcs[(beat + 1) % 3], 3), 0.5, 66))
                ev.append(('n', pm(pcs[(beat + 2) % 3], 4), 0.5, 62))
        return ev
    if s == 'A2':
        ev = []
        for beat in range(4):
            top = melody_midi(m, beat, 4, 60, 96, 1)
            mids = [pm(pcs[0], 2), pm(pcs[1], 3), pm(pcs[2], 3), fit(top, 60, 96)]
            ev.append(('c', mids, 1, 72 if beat == 0 else 66))
        return ev
    order = [(0, 2), (1, 3), (2, 3), (1, 3), (0, 3), (2, 3), (1, 4), (2, 3)]
    ev = []
    for i, pair in enumerate(order):
        pcidx, octv = pair
        art = 'staccato' if pos == 1 and i in (3, 7) else None
        ev.append(('n', pm(pcs[pcidx], octv), 0.5, 64 if i % 2 else 58, art))
    return ev

