def piano_events(bar):
    if bar <= 12:
        root = PROG_A[(bar - 1) % 4]
        tones = CHORDS[root]
        idx = [0, 2, 1, 3, 2, 4, 1, 2]
        return [(tones[i], 0.5) for i in idx]
    if 13 <= bar <= 28:
        root = PROG_B[(bar - 13) % 4]
        tones = CHORDS[root]
        return [(tones[:3], 2), (tones[0], 1), (tones[2], 1)]
    if 29 <= bar <= 40:
        root = PROG_A[(bar - 29) % 4]
        tones = CHORDS[root]
        idx = [4, 2, 3, 1, 2, 0, 1, 2]
        return [(tones[i], 0.5) for i in idx]
    root = ['D', 'B-', 'F', 'D'][bar - 41]
    return [(CHORDS[root][:4], 4)]

def cello_events(bar):
    if bar <= 12:
        root = PROG_A[(bar - 1) % 4]
    elif 13 <= bar <= 28:
        root = PROG_B[(bar - 13) % 4]
    elif 29 <= bar <= 40:
        root = PROG_A[(bar - 29) % 4]
    else:
        root = ['D', 'B-', 'F', 'D'][bar - 41]
    if bar <= 4 or 13 <= bar <= 28 or bar >= 41:
        return [(CELLO_ROOT[root], 4)]
    return [(CELLO_ROOT[root], 2), (CELLO_ROOT[root], 1), (CELLO_FIFTH[root], 1)]

def flute_events(bar):
    if bar in FLUTE_A:
        return FLUTE_A[bar]
    if bar in FLUTE_B:
        return FLUTE_B[bar]
    if bar in FLUTE_R:
        return FLUTE_R[bar]
    if bar in FLUTE_CODA:
        return FLUTE_CODA[bar]
    return [('rest', 4)]

def violin_events(bar):
    if bar in VIOLIN_A:
        return VIOLIN_A[bar]
    if 30 <= bar <= 37:
        return FLUTE_A[bar - 25]
    if 38 <= bar <= 40:
        return {38: [('A4', 2), ('C5', 2)], 39: [('B-4', 1), ('A4', 1), ('F4', 2)], 40: [('D4', 4)]}[bar]
    if bar in VIOLIN_CODA:
        return VIOLIN_CODA[bar]
    return [('rest', 4)]

def clarinet_events(bar):
    if bar in CLARINET_B:
        return CLARINET_B[bar]
    if bar == 44:
        return [('rest', 2), ('D5', 2)]
    return [('rest', 4)]

