def midi_name(m):
    p = pitch.Pitch()
    p.midi = int(round(m))
    return p.nameWithOctave

def fit(midi, low, high):
    midi = int(round(midi))
    while midi < low:
        midi += 12
    while midi > high:
        midi -= 12
    return midi

def deg_interval(degree):
    octave = degree // len(scale)
    return scale[degree % len(scale)] + 12 * octave

def flute_midi(root, degree):
    return fit(root + 24 + deg_interval(degree), 67, 91)

def clarinet_midi(root, degree):
    return fit(root + 12 + deg_interval(degree), 50, 82)

def violin_midi(root, degree):
    return fit(root + 24 + deg_interval(degree), 55, 88)

def piano_midi(root, degree):
    return fit(root + 12 + deg_interval(degree), 48, 81)

def create_event(pitches, dur, art=None):
    if pitches is None:
        e = note.Rest(quarterLength=dur)
    elif isinstance(pitches, list):
        e = chord.Chord([midi_name(x) for x in pitches], quarterLength=dur)
    else:
        e = note.Note(midi_name(pitches), quarterLength=dur)
    if art is not None and hasattr(e, 'articulations'):
        if art == 'staccato':
            e.articulations.append(articulations.Staccato())
        elif art == 'tenuto':
            e.articulations.append(articulations.Tenuto())
        elif art == 'accent':
            e.articulations.append(articulations.Accent())
    return e

def build_measure(number, events, dyn_mark=None):
    m = stream.Measure(number=number)
    if number == 1:
        m.insert(0, meter.TimeSignature('4/4'))
        m.insert(0, key.KeySignature(0))
    if dyn_mark is not None:
        m.insert(0, dynamics.Dynamic(dyn_mark))
    for pitches, dur, *extras in events:
        art = extras[0] if extras else None
        m.append(create_event(pitches, dur, art))
    return m

def make_flute_events(i, root):
    if i <= 8:
        pattern = flute_A[i - 1]
        shift = 0
    elif i <= 16:
        pattern = flute_B[i - 9]
        shift = 1
    else:
        pattern = flute_C[i - 17]
        shift = 0
    events = []
    for degree, dur in pattern:
        if degree is None:
            events.append((None, dur))
        else:
            art = 'accent' if i in (9, 13, 16) and dur <= 0.5 else None
            events.append((flute_midi(root, degree + shift), dur, art))
    return events

def make_clarinet_events(i, root):
    if i <= 8:
        a, b = clarinet_A[i - 1]
        return [(clarinet_midi(root, a), 2, 'tenuto'), (clarinet_midi(root, b), 2, 'tenuto')]
    if i <= 16:
        durations = [1, 0.5, 0.5, 1, 1]
        return [(clarinet_midi(root, d), q, 'tenuto' if q >= 1 else None) for d, q in zip(clarinet_B[i - 9], durations)]
    if i == 24:
        return [(clarinet_midi(root, 0), 4, 'tenuto')]
    a, b = clarinet_C[i - 17]
    return [(clarinet_midi(root, a), 3, 'tenuto'), (clarinet_midi(root, b), 1, 'tenuto')]

def make_violin_events(i, root):
    if i <= 8:
        d = violin_A_center[i - 1]
        return [([violin_midi(root, d), violin_midi(root, d + 2)], 2, 'tenuto'), ([violin_midi(root, d + 1), violin_midi(root, d + 3)], 2, 'tenuto')]
    if i <= 16:
        offset = (i - 9) % 3
        return [(violin_midi(root, d + offset), 0.5, 'staccato') for d in violin_B_pattern]
    if i == 24:
        return [([violin_midi(root, 7), violin_midi(root, 9)], 4, 'tenuto')]
    d = violin_C_center[i - 17]
    return [([violin_midi(root, d), violin_midi(root, d + 4)], 3, 'tenuto'), (violin_midi(root, d + 2), 1, 'tenuto')]

def make_piano_events(i, root):
    if i == 24:
        return [([36, 48, 55, 60, 64], 2, 'tenuto'), ([48, 55, 60, 64, 69], 2, 'tenuto')]
    if i <= 8:
        pattern = [0, 2, 4, 6, 4, 2, 1, 3]
    elif i <= 16:
        pattern = [0, 4, 2, 6, 5, 3, 1, 4]
    else:
        pattern = [0, 2, 4, 2, 0, 3, 5, 4]
    events = []
    for j, d in enumerate(pattern):
        if j in (0, 4):
            bass = fit(root + deg_interval(d), 36, 60)
            upper1 = piano_midi(root, d + 2)
            upper2 = piano_midi(root, d + 4)
            art = 'accent' if i in (8, 16) and j == 0 else 'tenuto'
            events.append(([bass, upper1, upper2], 0.5, art))
        else:
            events.append((piano_midi(root, d), 0.5))
    return events

def make_cello_events(i, root):
    root_low = fit(root - 12, 36, 55)
    fifth = fit(root_low + 7, 36, 67)
    octave = fit(root_low + 12, 36, 67)
    color = fit(root_low + 10, 36, 67)
    fourth = fit(root_low + 5, 36, 67)
    if i <= 8:
        return [(root_low, 2, 'tenuto'), (fifth, 1), (octave, 1)]
    if i <= 16:
        return [(root_low, 0.75, 'tenuto'), (fifth, 0.25), (octave, 1, 'accent'), (color, 0.5), (fifth, 0.5), (root_low, 1)]
    if i == 24:
        return [(36, 4, 'tenuto')]
    return [(root_low, 1.5, 'tenuto'), (fifth, 0.5), (fourth, 1), (root_low, 1, 'tenuto')]

