cello_roots = ['D2','D2','B-2','B-2','F2','F2','C2','C2','D2','D2','B-2','B-2','G2','G2','A2','A2','D2','F2','B-2','C2','D2','B-2','C2','D2']

def meas(num, dyn=None):
    m = stream.Measure()
    m.number = num
    if dyn is not None:
        m.insert(0, dynamics.Dynamic(dyn))
    return m

def n(pitch_name, ql):
    return note.Note(pitch_name, quarterLength=ql)

def r(ql):
    return note.Rest(quarterLength=ql)

def dyn_for(i, enter=1):
    if i == 24:
        return 'pp'
    if i == 17:
        return 'mf'
    if i == enter:
        return 'mp'
    if i == 1:
        return 'p'
    return None

for i, tones in enumerate(prog, start=1):
    m = meas(i, dyn_for(i, 1))
    root_up = pitch.Pitch(tones[0]).transpose(12).nameWithOctave
    seq = [tones[0], tones[2], tones[1], tones[2], root_up, tones[2], tones[1], tones[2]]
    for s in seq:
        m.append(n(s, 0.5))
    parts['Piano'].append(m)

for i, root in enumerate(cello_roots, start=1):
    m = meas(i, dyn_for(i, 1))
    fifth = pitch.Pitch(root).transpose(7).nameWithOctave
    if i in (8, 16, 24):
        m.append(n(root, 4.0))
    else:
        m.append(n(root, 2.0))
        m.append(n(fifth, 2.0))
    parts['Violoncello'].append(m)

for i, tones in enumerate(prog, start=1):
    m = meas(i, dyn_for(i, 3))
    if i < 3:
        m.append(r(4.0))
    else:
        high = [pitch.Pitch(t).transpose(12).nameWithOctave for t in tones]
        if i % 4 == 0:
            m.append(n(high[2], 2.0))
            m.append(n(high[1], 1.0))
            m.append(n(high[0], 1.0))
        elif i % 4 == 1:
            for s in [high[0], high[1], high[2], high[1]]:
                m.append(n(s, 1.0))
        elif i % 4 == 2:
            m.append(n(high[0], 2.0))
            m.append(n(high[2], 2.0))
        else:
            for s in [high[1], high[2], high[1], high[0]]:
                m.append(n(s, 1.0))
    parts['Violin'].append(m)

for i, tones in enumerate(prog, start=1):
    m = meas(i, dyn_for(i, 9))
    if i < 9:
        m.append(r(4.0))
    else:
        high = [pitch.Pitch(t).transpose(12).nameWithOctave for t in tones]
        if i in (15, 16):
            seq = [(high[0], 1.0), (high[1], 1.0), (high[2], 2.0)]
        elif i % 2 == 1:
            seq = [(high[0], 4.0)]
        else:
            seq = [(high[1], 2.0), (high[2], 2.0)]
        for s, ql in seq:
            m.append(n(s, ql))
    parts['Flute'].append(m)

for i, tones in enumerate(prog, start=1):
    m = meas(i, 'pp' if i == 1 else None)
    high = [pitch.Pitch(t).transpose(12).nameWithOctave for t in tones]
    if i == 24:
        m.append(chord.Chord(['D5','A5','D6'], quarterLength=4.0))
    elif i in (1, 5, 9, 13, 17, 21):
        m.append(chord.Chord([high[0], high[2]], quarterLength=4.0))
    else:
        m.append(r(4.0))
    parts['Vibraphone'].append(m)

