def t(base, semitones):
    n0 = note.Note(base)
    n0.transpose(semitones, inPlace=True)
    return n0.pitch.nameWithOctave

def n(pitch_name, ql, velocity=64, art=None):
    if pitch_name is None:
        return note.Rest(quarterLength=ql)
    obj = note.Note(pitch_name, quarterLength=ql)
    obj.volume.velocity = velocity
    if art == 'tenuto':
        obj.articulations.append(articulations.Tenuto())
    elif art == 'staccato':
        obj.articulations.append(articulations.Staccato())
    elif art == 'accent':
        obj.articulations.append(articulations.Accent())
    return obj

def ch(pitch_names, ql, velocity=54):
    obj = chord.Chord(pitch_names, quarterLength=ql)
    obj.volume.velocity = velocity
    return obj

def make_measure(number, contents, dyn=None):
    m = stream.Measure(number=number)
    if dyn is not None:
        m.insert(0, dynamics.Dynamic(dyn))
    for item in contents:
        m.append(item)
    return m

def make_part(part_id, inst):
    p = stream.Part(id=part_id)
    p.insert(0, inst)
    p.insert(0, meter.TimeSignature('4/4'))
    p.insert(0, key.KeySignature(0))
    p.insert(0, tempo.MetronomeMark(number=72, text='clear, patient'))
    return p

clarinet = make_part('Clarinet', instrument.Clarinet())
