def dyn_for_measure(i):
    if i == 1:
        return 'mp'
    if i == 9:
        return 'mf'
    if i == 17:
        return 'mp'
    if i == 25:
        return 'p'
    if i == 29:
        return 'pp'
    return None

def clarinet_query(center, velocity=66):
    return [n(None, 0.5), n(t(center, 0), 0.5, velocity, 'tenuto'), n(t(center, 2), 0.5, velocity), n(t(center, 4), 0.5, velocity), n(t(center, 7), 1.0, velocity, 'tenuto'), n(t(center, 6), 0.5, velocity), n(t(center, 4), 0.5, velocity)]

def clarinet_stream(center, velocity=72):
    intervals = [0, 3, 5, 7, 10, 9, 7, 5]
    return [n(t(center, x), 0.5, velocity, 'staccato' if j % 2 else None) for j, x in enumerate(intervals)]

def clarinet_answer(center, velocity=63):
    return [n(t(center, 0), 1.0, velocity, 'tenuto'), n(t(center, 2), 1.0, velocity), n(t(center, 4), 1.0, velocity), n(t(center, 7), 1.0, velocity, 'tenuto')]

def clarinet_release(center, velocity=54):
    return [n(None, 1.0), n(t(center, 0), 1.0, velocity, 'tenuto'), n(t(center, 2), 0.5, velocity), n(t(center, 4), 0.5, velocity), n(t(center, 7), 1.0, velocity, 'tenuto')]

def viola_memory(root, velocity=50):
    return [n(t(root, 7), 1.0, velocity), n(t(root, 4), 1.0, velocity), n(t(root, 9), 1.0, velocity), n(t(root, 7), 1.0, velocity)]

def viola_network(root, velocity=57):
    intervals = [0, 7, 10, 14, 12, 10, 7, 4]
    return [n(t(root, x), 0.5, velocity) for x in intervals]

def viola_chorale(root, velocity=49):
    return [ch([t(root, 0), t(root, 7)], 2.0, velocity), ch([t(root, 2), t(root, 9)], 2.0, velocity)]

def viola_release(root, velocity=42):
    return [n(t(root, 7), 1.5, velocity, 'tenuto'), n(None, 0.5), n(t(root, 4), 1.0, velocity), n(t(root, 2), 1.0, velocity)]

def cello_ground(root, velocity=44):
    return [n(root, 2.0, velocity, 'tenuto'), n(t(root, 7), 2.0, velocity)]

def cello_network(root, velocity=52):
    intervals = [0, 7, 12, 10]
    return [n(t(root, x), 1.0, velocity) for x in intervals]

def cello_chorale(root, velocity=43):
    return [n(root, 4.0, velocity, 'tenuto')]

def cello_release(root, velocity=38):
    return [n(root, 3.0, velocity, 'tenuto'), n(t(root, 7), 1.0, velocity)]

def piano_broken(pitches, velocity=47):
    return [ch([pitches[0], pitches[1]], 1.0, velocity), ch([pitches[2], pitches[3]], 1.0, velocity), ch([pitches[1], pitches[2], pitches[3]], 1.5, velocity), n(None, 0.5)]

def piano_shimmer(pitches, velocity=58):
    pairs = [(0, 2), (1, 3), (0, 3), (1, 2), (0, 2), (1, 3), (2, 3), (0, 1)]
    return [ch([pitches[a], pitches[b]], 0.5, velocity) for a, b in pairs]

def piano_chorale(pitches, velocity=51):
    return [ch(pitches, 2.0, velocity), ch([t(pitches[0], 12), pitches[1], pitches[2], pitches[3]], 2.0, velocity)]

def piano_bells(pitches, velocity=40):
    return [ch(pitches, 2.5, velocity), n(None, 0.5), ch([pitches[2], pitches[3]], 1.0, velocity)]

