def qlen(obj, q):
    obj.duration = m21.duration.Duration(q)
    return obj


def N(p, q):
    n = m21.note.Note(p)
    return qlen(n, q)


def R(q):
    r = m21.note.Rest()
    return qlen(r, q)


def Ch(pitches, q):
    c = m21.chord.Chord(pitches)
    return qlen(c, q)


def P(pc, octave):
    return pc + str(octave)


def bass_octave(pc):
    if pc[0] in ['A', 'B']:
        return 1
    return 2


