def piano_events(harmony, number):
    root, tones = harmony
    bo = bass_octave(root)
    if number == 36:
        final_chord = Ch(['E2', 'B2', 'E3', 'F#4', 'G#4', 'B4'], 4)
        final_chord.expressions.append(m21.expressions.Fermata())
        return [final_chord]
    low = [P(root, bo), P(tones[2], bo + 1)]
    mid = [P(tones[1], 3), P(tones[3], 4), P(tones[4], 4)]
    high = [P(root, 3), P(tones[2], 4), P(tones[3], 4), P(tones[4], 5)]
    if 9 <= number <= 16:
        events = []
        for k in range(8):
            if k % 2 == 0:
                events.append(Ch(low, 0.5))
            else:
                events.append(Ch([P(tones[1], 4), P(tones[3], 4), P(tones[4], 5)], 0.5))
        return events
    if 17 <= number <= 24:
        return [
            Ch(low, 1),
            Ch([P(tones[1], 4), P(tones[2], 4), P(tones[3], 4)], 0.5),
            Ch([P(tones[2], 3), P(tones[4], 4)], 0.5),
            Ch([P(root, bo + 1), P(tones[3], 4), P(tones[4], 5)], 1),
            Ch([P(tones[1], 4), P(tones[2], 4), P(tones[4], 5)], 1)
        ]
    return [
        Ch(low, 1.5),
        Ch(mid, 0.5),
        Ch([P(root, bo + 1), P(tones[2], 3), P(tones[3], 4)], 1),
        Ch(high, 1)
    ]


