    pcs = [root, tones[2], tones[1], tones[3], tones[4], tones[3], tones[1], tones[2]]
    octaves = [3, 3, 4, 4, 5, 4, 4, 3]
    events = []
    if 9 <= number <= 16:
        for k in range(16):
            events.append(N(P(pcs[k % 8], octaves[k % 8]), 0.25))
