        return [R(2), N(P(tones[2], 5), 0.5), N(P(tones[4], 5), 0.5), N(P(tones[3], 5), 1)]
    if 9 <= number <= 16:
        pcs = [tones[4], tones[3], tones[2], tones[1], tones[2], tones[3], tones[4], root]
