    if number % 3 == 0:
        return [R(2), N(P(tones[4], 5), 1), N(P(tones[3], 5), 1)]
    return [R(1), N(P(tones[2], 5), 1), R(0.5), N(P(tones[4], 5), 0.5), N(P(root, 6), 1)]


