def viola_events(harmony, number):
    if number == 36:
        n = N('B3', 4)
        n.expressions.append(m21.expressions.Fermata())
        return [n]
    root, tones = harmony
    if number <= 8:
        return [N(P(tones[2], 3), 2), N(P(tones[3], 4), 2)]
    if 9 <= number <= 24:
        return [N(P(tones[1], 3), 1), N(P(tones[2], 3), 1), N(P(tones[3], 4), 1), N(P(tones[4], 4), 1)]
    return [N(P(tones[2], 3), 3), N(P(tones[1], 3), 1)]


def cello_events(harmony, number):
    if number == 36:
        n = N('E2', 4)
        n.expressions.append(m21.expressions.Fermata())
        return [n]
    root, tones = harmony
    co = bass_octave(root)
    bass = P(root, co)
    fifth = P(tones[2], co + 1)
    if number <= 8 or number >= 25:
        return [N(bass, 4)]
    return [N(bass, 2), N(fifth, 1), N(bass, 1)]


