def h(m):
    return harmonies[(m - 1) % len(harmonies)]

def tr(p, semis):
    if p is None:
        return None
    return pitch.Pitch(p).transpose(semis).nameWithOctave

def transpose_line(line, semis):
    out = []
    for ev in line:
        p = ev[0]
        dur = ev[1]
        marks = ev[2] if len(ev) > 2 else None
        if p is None:
            np = None
        elif isinstance(p, (list, tuple)):
            np = [tr(x, semis) for x in p]
        else:
            np = tr(p, semis)
        if marks is None:
            out.append((np, dur))
        else:
            out.append((np, dur, marks))
    return out

def reverse_line(line):
    rev = []
    for ev in reversed(line):
        if len(ev) > 2:
            rev.append((ev[0], ev[1], ev[2]))
        else:
            rev.append((ev[0], ev[1]))
    return rev

def make_obj(p, dur):
    if p is None:
        obj = note.Rest()
    elif isinstance(p, (list, tuple)):
        obj = chord.Chord(list(p))
    else:
        obj = note.Note(p)
    obj.duration.quarterLength = dur
    return obj

def apply_marks(obj, marks):
    if isinstance(marks, str):
        marks = [marks]
    for mark in marks:
        if mark == 'accent':
            obj.articulations.append(articulations.Accent())
        elif mark == 'tenuto':
            obj.articulations.append(articulations.Tenuto())
        elif mark == 'staccato':
            obj.articulations.append(articulations.Staccato())
        elif mark == 'fermata':
            obj.expressions.append(expressions.Fermata())

def measure_from_events(number, events, dyn=None, text=None, first=False):
    m = stream.Measure(number=number)
    if first:
        m.insert(0, time_signature)
        m.insert(0, home_key)
    if dyn is not None:
        m.insert(0, dynamics.Dynamic(dyn))
    if text is not None:
        te = expressions.TextExpression(text)
        te.placement = 'above'
        m.insert(0, te)
    total = 0.0
    for ev in events:
        p = ev[0]
        dur = ev[1]
        marks = ev[2] if len(ev) > 2 else []
        obj = make_obj(p, dur)
        if p is not None and marks:
            apply_marks(obj, marks)
        m.append(obj)
        total += float(dur)
    remaining = 4.0 - total
    if remaining > 0.0001:
        r = note.Rest()
        r.duration.quarterLength = remaining
        m.append(r)
    return m

def piano_lh_events(m):
    hh = h(m)
    b = hh['bass']
    if m == measure_count:
        return [(['D2', 'D3'], 4.0, ['fermata'])]
    if m >= 41:
        return [(b[0], 2.0, ['tenuto']), (b[1], 1.0), (b[2], 1.0)]
    if 33 <= m <= 40:
        return [(b[0], 0.5, ['accent']), (b[1], 0.5), ([b[0], b[2]], 1.0, ['accent']), (b[3], 0.5), (b[4], 0.5), ([b[1], b[5]], 1.0)]
    return [(b[i], 0.5) for i in range(8)]

def piano_rh_events(m):
    hh = h(m)
    c = hh['chord']
    if m == measure_count:
        return [(['D4', 'F4', 'A4', 'C#5', 'E5'], 4.0, ['fermata'])]
    if m <= 8:
        return [(None, 0.5), ([c[0], c[1], c[3]], 1.0), (None, 0.5), ([c[1], c[2], c[3]], 1.0), ([c[0], c[2]], 1.0)]
    if m <= 20:
        seq = [c[0], c[1], c[2], c[3], tr(c[0], 12), tr(c[1], 12), c[2], c[1]]
        return [(p, 0.5) for p in seq]
    if m <= 32:
        return [([c[0], c[1], c[2]], 2.0, ['tenuto']), ([c[1], c[2], c[3]], 1.0), ([tr(c[0], 12), c[3]], 1.0)]
    if m <= 40:
        big = [tr(hh['bass'][0], 24), c[0], c[1], c[2], c[3]]
        return [(big, 1.0, ['accent']), ([c[1], c[2], tr(c[3], 12)], 1.0), (big, 1.0, ['accent']), ([c[0], tr(c[1], 12), tr(c[2], 12)], 1.0)]
    return [(None, 1.0), ([c[2], c[3]], 1.5, ['tenuto']), (None, 0.5), ([c[0], tr(c[0], 12)], 1.0)]

def cello_events(m):
    hh = h(m)
    b = hh['bass']
    if m == measure_count:
        return [('D2', 4.0, ['fermata'])]
    if m <= 8:
        return [(b[0], 3.0, ['tenuto']), (b[1], 1.0)]
    if m <= 20:
        return [(b[0], 1.5), (b[2], 0.5), (b[1], 1.0), (b[3], 1.0)]
    if m <= 32:
        return [(b[0], 2.0, ['tenuto']), (b[3], 2.0)]
    if m <= 40:
        return [(b[0], 1.0, ['accent']), (b[0], 0.5), (b[1], 0.5), (b[2], 1.0), (b[3], 1.0)]
    return [(b[0], 4.0, ['tenuto'])]

def viola_events(m):
    hh = h(m)
    b = hh['bass']
    c = hh['chord']
    if m == measure_count:
        return [('F3', 4.0, ['fermata'])]
    if m <= 8:
        return [(b[3], 4.0, ['tenuto'])]
    if m <= 20:
        return [(b[3], 1.0), (c[0], 1.0), (c[1], 1.0), (c[0], 1.0)]
    if m <= 32:
        return [(b[3], 2.0, ['tenuto']), (b[4], 2.0)]
    if m <= 40:
        seq = [b[3], c[0], b[4], c[1], b[3], c[2], c[1], c[0]]
        return [(p, 0.5) for p in seq]
    return [(b[3], 2.0, ['tenuto']), (c[0], 2.0)]

def violin_events(m):
    if m == measure_count:
        return [('D5', 4.0, ['fermata'])]
    if m <= 4:
        return [('D5', 4.0, ['tenuto'])]
    if m <= 8:
        return [('D5', 1.5), (None, 0.5), ('E5', 1.0), ('A4', 1.0)]
    if m <= 20:
        line = motif_a if m % 2 else motif_b
        if m % 4 == 0:
            line = reverse_line(line)
        return transpose_line(line, shift_cycle[(m - 9) % len(shift_cycle)])
    if m <= 32:
        shift = shift_cycle[(m - 21) % len(shift_cycle)]
        return transpose_line([('F5', 2.0, ['tenuto']), ('E5', 1.0), ('C#5', 1.0)], shift)
    if m <= 40:
        return transpose_line(climax_motif, shift_cycle[(m - 33) % len(shift_cycle)])
    coda = {
        41: [('A5', 2.0), ('F5', 1.0), ('E5', 1.0)],
        42: [('C#5', 2.0), ('D5', 2.0)],
        43: [('B4', 1.0), ('C#5', 1.0), ('A4', 2.0)],
        44: [('F4', 2.0), ('E4', 1.0), ('D4', 1.0)],
        45: [('A4', 2.0), ('C#5', 2.0)],
        46: [('E5', 1.0), ('F5', 1.0), ('D5', 2.0)],
        47: [('C#5', 2.0), ('A4', 1.0), ('D5', 1.0)]
    }
    return coda.get(m, [('D5', 4.0)])

def clarinet_events(m):
    if m == measure_count:
        return [('A3', 4.0, ['fermata'])]
    if m <= 4:
        return [(None, 4.0)]
    if m <= 8:
        return [(None, 1.0), ('D4', 1.0), ('E4', 0.5), ('A3', 0.5), ('C#4', 1.0)]
    if m <= 20:
        return transpose_line(clarinet_motif, shift_cycle[(m - 9) % len(shift_cycle)])
    if m <= 32:
        c = h(m)['chord']
        return [(tr(c[0], -12), 2.0, ['tenuto']), (tr(c[1], -12), 1.0), (tr(c[2], -12), 1.0)]
    if m <= 40:
        c = h(m)['chord']
        seq = [tr(c[0], -12), tr(c[1], -12), c[0], c[1], c[2], c[1], c[0], tr(c[2], -12)]
        return [(p, 0.5) for p in seq]
    coda = {
        41: [('E4', 2.0), ('D4', 2.0)],
        42: [('C#4', 2.0), ('A3', 2.0)],
        43: [('B3', 2.0), ('A3', 2.0)],
        44: [('F3', 2.0), ('E3', 2.0)],
        45: [('A3', 4.0, ['tenuto'])],
        46: [('C#4', 2.0), ('B3', 2.0)],
        47: [('A3', 2.0), ('C#4', 1.0), ('A3', 1.0)]
    }
    return coda.get(m, [('A3', 4.0)])

def flute_events(m):
    if m == measure_count:
        return [('D6', 4.0, ['fermata'])]
    if m <= 4:
        return [(None, 2.0), ('D6', 1.0, ['tenuto']), (None, 1.0)]
    if m <= 8:
        return transpose_line(flute_spark, shift_cycle[(m - 5) % len(shift_cycle)])
    if m <= 20:
        line = [('E6', 1.0), (None, 0.5), ('D6', 0.5), ('A5', 1.0), ('C#6', 1.0)]
        return transpose_line(line, shift_cycle[(m - 9) % len(shift_cycle)])
    if m <= 32:
        return transpose_line([('A5', 2.0, ['tenuto']), ('C#6', 2.0)], shift_cycle[(m - 21) % len(shift_cycle)])
    if m <= 40:
        line = [('A5', 0.5), ('C#6', 0.5), ('E6', 0.5), ('F6', 0.5), ('A6', 1.0), ('E6', 0.5), ('D6', 0.5)]
        return transpose_line(line, shift_cycle[(m - 33) % len(shift_cycle)])
    coda = {
        41: [('A6', 1.0), (None, 1.0), ('F6', 1.0), ('E6', 1.0)],
        42: [('D6', 2.0), ('C#6', 2.0)],
        43: [('B5', 1.0), ('A5', 1.0), (None, 2.0)],
        44: [('F5', 2.0), ('E5', 2.0)],
        45: [('A5', 2.0), ('C#6', 2.0)],
        46: [('E6', 1.0), ('F6', 1.0), ('D6', 2.0)],
        47: [('C#6', 2.0), ('A5', 1.0), ('D6', 1.0)]
    }
    return coda.get(m, [('D6', 4.0)])

def dyn_for(m):
    return section_dynamics.get(m, None)

def build_part(part_id, part_name, inst, event_func, include_text=False):
    p = stream.Part(id=part_id)
    p.partName = part_name
    p.insert(0, inst)
    for m in range(1, measure_count + 1):
        text = section_text.get(m, None) if include_text else None
        p.append(measure_from_events(m, event_func(m), dyn=dyn_for(m), text=text, first=(m == 1)))
    return p

flute_part = build_part('Flute', 'Flute', instrument.Flute(), flute_events)
clarinet_part = build_part('Clarinet', 'Clarinet', instrument.Clarinet(), clarinet_events)
violin_part = build_part('Violin', 'Violin', instrument.Violin(), violin_events)
viola_part = build_part('Viola', 'Viola', instrument.Viola(), viola_events)
cello_part = build_part('Violoncello', 'Violoncello', instrument.Violoncello(), cello_events)
piano_rh_part = build_part('Piano_RH', 'Piano', instrument.Piano(), piano_rh_events, include_text=True)
piano_lh_part = build_part('Piano_LH', 'Piano', instrument.Piano(), piano_lh_events)

for part in [flute_part, clarinet_part, violin_part, viola_part, cello_part, piano_rh_part, piano_lh_part]:
    score.insert(0, part)

import math
