tempo_mark = m21.tempo.MetronomeMark(number=100)

celesta = m21.stream.Part()
celesta.id = 'Celesta'
celesta.insert(0, m21.instrument.Celesta())

piano = m21.stream.Part()
piano.id = 'Piano'
piano.insert(0, m21.instrument.Piano())

vln1 = m21.stream.Part()
