vln2.insert(0, m21.instrument.Violin())

vla = m21.stream.Part()
vla.id = 'Viola'
vla.insert(0, m21.instrument.Viola())

vc = m21.stream.Part()
vc.id = 'Violoncello'
vc.insert(0, m21.instrument.Violoncello())

scale_c_lyd = ['C', 'D', 'E', 'F#', 'G', 'A', 'B']
scale_e_lyd_dom = ['E', 'F#', 'G#', 'A#', 'B', 'C#', 'D']
scale_fs_lyd = ['F#', 'G#', 'A#', 'B#', 'C#', 'D#', 'E#']

def get_pitch(scale, degree, octave):
    pc = scale[degree % len(scale)]
    oct_shift = degree // len(scale)
    return f"{pc}{octave + oct_shift}"

num_measures = 48
parts = [celesta, piano, vln1, vln2, vla, vc]
part_measures = {p.id: [] for p in parts}

for p in parts:
    for i in range(num_measures):
        m = m21.stream.Measure(number=i+1)
        if i == 0:
            m.insert(0, m21.meter.TimeSignature('4/4'))
            m.insert(0, tempo_mark)
        part_measures[p.id].append(m)

for m in range(1, num_measures + 1):
    m_idx = m - 1

    if m <= 10:
        current_scale = scale_c_lyd
        root = 'C'
    elif m <= 22:
        current_scale = scale_e_lyd_dom
        root = 'E'
    elif m <= 36:
        current_scale = scale_fs_lyd
        root = 'F#'
    else:
        current_scale = scale_c_lyd
        root = 'C'

    if m == 1:
        part_measures['Celesta'][m_idx].insert(0, m21.dynamics.Dynamic('pp'))
        part_measures['Piano'][m_idx].insert(0, m21.dynamics.Dynamic('p'))
        part_measures['Violoncello'][m_idx].insert(0, m21.dynamics.Dynamic('pp'))
    elif m == 5:
        part_measures['Piano'][m_idx].insert(0, m21.dynamics.Dynamic('mp'))
        part_measures['Viola'][m_idx].insert(0, m21.dynamics.Dynamic('p'))
    elif m == 7:
        part_measures['Violin1'][m_idx].insert(0, m21.dynamics.Dynamic('p'))
    elif m == 9:
        part_measures['Violin2'][m_idx].insert(0, m21.dynamics.Dynamic('mp'))
    elif m == 11:
        part_measures['Celesta'][m_idx].insert(0, m21.dynamics.Dynamic('mf'))
        part_measures['Piano'][m_idx].insert(0, m21.dynamics.Dynamic('mf'))
        part_measures['Violoncello'][m_idx].insert(0, m21.dynamics.Dynamic('mf'))
    elif m == 13:
        part_measures['Violin1'][m_idx].insert(0, m21.dynamics.Dynamic('mf'))
        part_measures['Viola'][m_idx].insert(0, m21.dynamics.Dynamic('mf'))
    elif m == 23:
        for p in parts:
            part_measures[p.id][m_idx].insert(0, m21.dynamics.Dynamic('ff'))
    elif m == 37:
        for p in parts:
            part_measures[p.id][m_idx].insert(0, m21.dynamics.Dynamic('mp'))
    elif m == 43:
        for p in parts:
            part_measures[p.id][m_idx].insert(0, m21.dynamics.Dynamic('ppp'))

    # Celesta
    m_cel = part_measures['Celesta'][m_idx]
    if m <= 2:
        m_cel.append(m21.note.Rest(quarterLength=4.0))
    elif m <= 38:
        for sixteenth in range(16):
            idx = int(3 * m + 5 * sixteenth + math.sin(m + sixteenth)*2) % (len(current_scale) * 2)
            p_str = get_pitch(current_scale, idx, 5)
            m_cel.append(m21.note.Note(p_str, quarterLength=0.25))
    elif m < 48:
        m_cel.append(m21.note.Note(get_pitch(current_scale, (m * 2) % 7, 6), quarterLength=2.0))
        m_cel.append(m21.note.Rest(quarterLength=2.0))
    else:
        m_cel.append(m21.note.Note('C6', quarterLength=4.0))

    # Piano
    m_pno = part_measures['Piano'][m_idx]
    if m <= 4:
        if m % 2 == 1:
            c1 = m21.chord.Chord([f"{root}2", f"{current_scale[4]}2"], quarterLength=2.0)
            c2 = m21.chord.Chord([f"{current_scale[0]}3", f"{current_scale[2]}3", f"{current_scale[3]}3", f"{current_scale[6]}3"], quarterLength=2.0)
            m_pno.append(c1)
            m_pno.append(c2)
        else:
            c1 = m21.chord.Chord([f"{root}2", f"{current_scale[1]}3", f"{current_scale[4]}3"], quarterLength=4.0)
            m_pno.append(c1)
    elif m <= 22:
        for q in range(4):
            if q % 2 == 0:
                ch_notes = [get_pitch(current_scale, (q + m) % 7, 3), get_pitch(current_scale, (q + m + 2) % 7, 3), get_pitch(current_scale, (q + m + 4) % 7, 4)]
                m_pno.append(m21.chord.Chord(ch_notes, quarterLength=1.0))
