    elif m < 48:
        ch_notes = [get_pitch(current_scale, 0, 2), get_pitch(current_scale, 2, 3), get_pitch(current_scale, 4, 3), get_pitch(current_scale, 6, 3)]
        m_pno.append(m21.chord.Chord(ch_notes, quarterLength=4.0))
