def pooled_events(pool, durations, shift=0, rests=(), reverse=False):
    contour = [0, 1, 3, 2, 1, 0, 2, 3, 1, 2]
    if reverse:
        contour = [3, 2, 0, 1, 2, 3, 1, 0, 2, 1]
    result = []
    for i, duration in enumerate(durations):
        chosen = None if i in rests else pool[(contour[i % len(contour)] + shift) % len(pool)]
        result.append((chosen, duration))
    return result


def transposed_pool(pool, semitones):
    return [pitch.Pitch(p).transpose(semitones).nameWithOctave for p in pool]


def melodic_events(part_name, measure_number):
    if part_name == 'Flute':
        if measure_number <= 10:
            rests = (0,) if measure_number in (1, 4, 7) else ()
            return pooled_events(a_flute_pools[measure_number - 1], a_flute_rhythms[measure_number - 1], (measure_number - 1) % 2, rests)
        if measure_number <= 20:
            pool = b_flute_pools[measure_number - 11]
            rests = (3,) if measure_number in (14, 19) else ()
            return pooled_events(pool, [0.5] * 8, (measure_number - 11) % 3, rests)
        if measure_number <= 28:
            idx = measure_number - 21
            rests = (0,) if measure_number in (21, 26) else ()
            return pooled_events(c_flute_pools[idx], c_rhythms[idx], idx % 2, rests)
        if measure_number <= 36:
            idx = measure_number - 29
            return pooled_events(d_flute_pools[idx], [0.5, 0.5, 0.5, 0.5, 1, 0.5, 0.5], idx % 3)
        return flute_endings[measure_number]

    if measure_number <= 10:
        pool = transposed_pool(a_flute_pools[measure_number - 1], -7)
        rests = (0,) if measure_number in (1, 2, 5, 10) else ()
        return pooled_events(pool, a_clarinet_rhythms[measure_number - 1], measure_number % 2, rests, reverse=True)
    if measure_number <= 20:
        pool = transposed_pool(b_flute_pools[measure_number - 11], -7)
        rests = (0,) if measure_number in (11, 16) else ()
        return pooled_events(pool, [0.5, 0.5, 1, 0.5, 0.5, 1], measure_number % 3, rests, reverse=True)
    if measure_number <= 28:
        idx = measure_number - 21
        pool = transposed_pool(c_flute_pools[idx], -5)
        rests = (0,) if measure_number in (23, 27) else ()
        return pooled_events(pool, list(reversed(c_rhythms[idx])), idx % 2, rests, reverse=True)
    if measure_number <= 36:
        idx = measure_number - 29
        pool = transposed_pool(d_flute_pools[idx], -7)
        return pooled_events(pool, [0.75, 0.25, 0.5, 0.5, 0.75, 0.25, 1], idx % 2, reverse=True)
    return clarinet_endings[measure_number]


def cello_events(measure_number):
    v = voicings[measure_number - 1]
    if measure_number <= 10:
        return [(v[0], 2), (v[1], 2)]
    if measure_number <= 20:
        return [(v[0], 1), (v[1], 1), (v[2], 1), (v[1], 1)]
    if measure_number <= 28:
        return [(v[0], 3), (v[1], 1)]
    if measure_number <= 36:
        return [(v[0], 1), (v[1], 0.5), (v[2], 0.5), (v[0], 1), (v[1], 1)]
    if measure_number == 38:
        return [('D2', 2), ('Bb1', 2)]
    if measure_number == 39:
        return [('A1', 4)]
    return [('D2', 4)]


def piano_events(measure_number):
    v = voicings[measure_number - 1]
    if measure_number <= 10:
        pattern = [0, 2, 3, 4, 5, 4, 3, 2]
        return [(v[i], 0.5) for i in pattern]
    if measure_number <= 20:
        pattern = [0, 2, 3, 4, 5, 4, 3, 2, 1, 2, 4, 5, 4, 3, 2, 1]
        return [(v[i], 0.25) for i in pattern]
    if measure_number <= 28:
        return [(v, 2), (None, 0.5), ([v[4], v[5]], 1.5)]
    if measure_number <= 36:
        durations = [0.5, 0.5, 0.25, 0.25, 0.5, 0.5, 0.5, 0.25, 0.25, 0.5]
        pattern = [0, 2, 3, 4, 5, 3, 4, 2, 5, 1]
        return [(v[i], d) for i, d in zip(pattern, durations)]
    if measure_number == 37:
        return [(v, 4)]
    if measure_number == 38:
        return [(v[0], 1), (v, 3)]
    if measure_number == 39:
        return [(v, 2), ([v[4], v[5]], 2)]
    return [(v, 4)]


def put_events(measure, events):
    total = sum(float(duration) for _, duration in events)
    if total > 4.000001:
        raise ValueError('Measure exceeds four quarter notes')
    created = []
    for pitches, duration in events:
        if pitches is None:
            obj = note.Rest(quarterLength=duration)
        elif isinstance(pitches, (list, tuple)):
            obj = chord.Chord(pitches, quarterLength=duration)
        else:
            obj = note.Note(pitches, quarterLength=duration)
        measure.append(obj)
        created.append(obj)
    if total < 3.999999:
        r = note.Rest(quarterLength=4 - total)
        measure.append(r)
        created.append(r)
    return created


part_specs = [
    ('Flute', instrument.Flute(), clef.TrebleClef()),
    ('Clarinet', instrument.Clarinet(), clef.TrebleClef()),
    ('Violoncello', instrument.Violoncello(), clef.BassClef()),
    ('Piano', instrument.Piano(), clef.TrebleClef())
]

for part_name, part_instrument, opening_clef in part_specs:
    part = stream.Part(id=part_name.replace(' ', '_'))
    part.partName = part_name
    part.insert(0, part_instrument)

    for measure_number in range(1, TOTAL_MEASURES + 1):
        measure = stream.Measure(number=measure_number)

        if measure_number == 1:
            measure.insert(0, meter.TimeSignature('4/4'))
            measure.insert(0, opening_clef)
        if measure_number in key_changes:
            measure.insert(0, key.KeySignature(key_changes[measure_number]))
        if measure_number in dynamic_marks:
            measure.insert(0, dynamics.Dynamic(dynamic_marks[measure_number]))

        if part_name == 'Flute':
            if measure_number in tempo_changes:
                measure.insert(0, tempo.MetronomeMark(number=tempo_changes[measure_number]))
            if measure_number in section_names:
                measure.insert(0, expressions.TextExpression(section_names[measure_number]))
            if measure_number == 39:
                measure.insert(0, expressions.TextExpression('rit. — let the horizon widen'))

        if part_name in ('Flute', 'Clarinet'):
            events = melodic_events(part_name, measure_number)
        elif part_name == 'Violoncello':
            events = cello_events(measure_number)
        else:
            events = piano_events(measure_number)

        created = put_events(measure, events)

        if part_name in ('Flute', 'Clarinet') and 11 <= measure_number <= 20:
            for i, obj in enumerate(created):
                if isinstance(obj, note.Note) and i % 2 == 1:
                    obj.articulations.append(articulations.Staccato())
        if part_name in ('Flute', 'Clarinet') and 21 <= measure_number <= 28:
            for obj in created:
                if isinstance(obj, note.Note):
                    obj.articulations.append(articulations.Tenuto())
        if 29 <= measure_number <= 36:
            for i, obj in enumerate(created):
                if isinstance(obj, (note.Note, chord.Chord)) and i in (0, 4):
                    obj.articulations.append(articulations.Accent())

        if part_name == 'Violoncello' and measure_number == 1:
            measure.insert(0, expressions.TextExpression('pizz., like a distant pulse'))
        if part_name == 'Violoncello' and measure_number == 21:
            measure.insert(0, expressions.TextExpression('arco, sul tasto'))
        if part_name == 'Violoncello' and measure_number == 29:
            measure.insert(0, expressions.TextExpression('ordinario, energized'))
        if part_name == 'Piano' and measure_number == 1:
            measure.insert(0, expressions.TextExpression('transparent, with generous resonance'))

        if measure_number == TOTAL_MEASURES:
            for obj in reversed(created):
                if isinstance(obj, (note.Note, chord.Chord)):
                    obj.expressions.append(expressions.Fermata())
                    break
            measure.rightBarline = bar.Barline('final')

        part.append(measure)

    score.insert(0, part)

